values ('7e570000-0000-4000-8000-000000000013', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-supreme-pommes-puree-tarragon-jus', 'chicken-supreme-pommes-puree-tarragon-jus', 'Pan-Roasted Chicken Supreme, Pommes Purée, Glazed Carrots & Tarragon Jus', 'A restaurant-style composed plate: crisp-skinned chicken, silky buttered potato purée, glossy carrots and a bright tarragon pan jus.', 'french', 4, 45, 60, 105, 2, 'main', null, 0, array['stove', 'oven']::text[], array['date-night', 'composed-plate']::text[], array['Service timeline: start the potatoes first, carrots 25 minutes before plating, chicken 25 minutes before, jus while the chicken rests.', 'Salt the chicken 1 hour ahead (or overnight, uncovered in the fridge) for crisper skin.', 'Spoon the jus around the chicken, not over the skin, so it stays crisp.', 'Warm the plates in a low oven before plating.']::text[], 'https://images.unsplash.com/photo-1788462612914-44793f2980f2', 'Chicken breast with sauce, mashed potatoes and vegetables', 'gabbiistudios', 'https://unsplash.com/@gabrielonodegba', 'https://unsplash.com/photos/chicken-dinner-with-mushroom-sauce-UdO-JP67I-4', 'unsplash', true, 'public', false,
