insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e570000-0000-4000-8000-000000000019', 1, null, 'Melt the butter in a light-coloured saucepan over medium heat, swirling, until it smells nutty and the solids turn golden brown, 5–7 minutes. Pour into a large bowl and cool 10 minutes.', 360, null, null),
  ('7e570000-0000-4000-8000-000000000019', 2, null, 'Whisk in both sugars, then the egg, yolk and vanilla until glossy.', null, null, null),
  ('7e570000-0000-4000-8000-000000000019', 3, null, 'Stir in the flour, baking soda and salt, then the chocolate. Chill the dough 30 minutes so it holds its shape.', 1800, null, null),
  ('7e570000-0000-4000-8000-000000000019', 4, null, 'Heat the oven to 350°F. Scoop 2-tablespoon balls onto lined sheets, 2 inches apart.', null, 176.7, null),
  ('7e570000-0000-4000-8000-000000000019', 5, null, 'Bake until the edges are golden and the centres still look soft, 10–12 minutes. Sprinkle with flaky salt and cool on the sheet 5 minutes.', 660, 176.7, null);

