insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e570000-0000-4000-8000-000000000023', 1, 'Pastry cream', 'Heat the milk until steaming. Whisk the yolks, sugar and cornstarch, then slowly whisk in the hot milk.', null, null, null),
  ('7e570000-0000-4000-8000-000000000023', 2, 'Pastry cream', 'Return to the pan and whisk over medium heat until it boils and thickens, then keep whisking 1 minute more so the starch cooks out.', 60, null, null),
  ('7e570000-0000-4000-8000-000000000023', 3, 'Pastry cream', 'Off the heat, whisk in the butter and vanilla. Press plastic onto the surface and chill until cold, at least 2 hours.', 7200, null, null),
  ('7e570000-0000-4000-8000-000000000023', 4, 'Choux', 'Heat the oven to 400°F and line two sheets with parchment.', null, 204.4, null),
  ('7e570000-0000-4000-8000-000000000023', 5, 'Choux', 'Bring the water, milk, butter, sugar and salt to a full boil. Add the flour all at once and stir over medium heat until the dough pulls into a ball and films the pan, about 2 minutes.', 120, null, null),
  ('7e570000-0000-4000-8000-000000000023', 6, 'Choux', 'Cool the dough 3 minutes, then beat in the eggs one at a time until glossy and it falls from the spoon in a thick V.', null, null, null),
  ('7e570000-0000-4000-8000-000000000023', 7, 'Choux', 'Pipe 1½-inch mounds 2 inches apart. Bake 20 minutes, then lower to 350°F and bake until deep golden and dry, 15–20 minutes more.', 2280, 204.4, null),
  ('7e570000-0000-4000-8000-000000000023', 8, 'Choux', 'Pierce each puff to let steam escape and cool completely on a rack.', null, null, null),
  ('7e570000-0000-4000-8000-000000000023', 9, 'To finish', 'Whisk the pastry cream smooth, pipe it into the puffs through a small hole in the base, and dust with powdered sugar.', null, null, null);

