values ('6199953b-f091-486d-ad80-621036ba19d0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'buttermilk-fried-chicken', 'buttermilk-fried-chicken-619995', 'Buttermilk Fried Chicken', 'Bone-in chicken soaked overnight in seasoned buttermilk, then fried in a craggy, well-spiced crust that stays crunchy for hours.', 'american', 2, 30, 40, 70, 4, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'entertaining']::text[], array['A clip-on thermometer makes this much easier: the oil temperature drops when the chicken goes in, so start a little hot and adjust the burner to hold it near 325°F.', 'Never leave hot oil unattended, and let it cool completely before straining or throwing it away.']::text[], 'https://images.pexels.com/photos/33254639/pexels-photo-33254639.jpeg', 'Crispy golden fried chicken pieces piled on a black plate', 'Alankrit Saini', 'https://www.pexels.com/@alankrit-saini-14865083/', 'https://www.pexels.com/photo/close-up-of-crispy-fried-chicken-on-plate-33254639/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday', 'entertaining']::text[], array['fry']::text[], array['spicy', 'tangy']::text[], array['picnic', 'july-4th']::text[], 'Southern', 'traditional', 'fried-chicken', 'classic', 'Refrigerate up to 3 days. Re-crisp on a rack at 375°F for 12–15 minutes — or eat it cold.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['buttermilk', 'sauce', 'cornstarch', 'paprika', 'garlic powder', 'onion powder', 'cayenne pepper']::text[], 'buttermilk|cayenne pepper|cornstarch|garlic powder|onion powder|paprika|sauce',
