  ('6199953b-f091-486d-ad80-621036ba19d0', 5, 'Buttermilk soak', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 6, 'Seasoned flour', '2 cups all-purpose flour', 'all-purpose flour', 2, 'cup', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 7, 'Seasoned flour', '½ cup cornstarch', 'cornstarch', 0.5, 'cup', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 8, 'Seasoned flour', '2 tsp kosher salt', 'kosher salt', 2, 'tsp', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 9, 'Seasoned flour', '2 tsp paprika', 'paprika', 2, 'tsp', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 10, 'Seasoned flour', '1 tsp garlic powder', 'garlic powder', 1, 'tsp', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 11, 'Seasoned flour', '1 tsp onion powder', 'onion powder', 1, 'tsp', null, false),
  ('6199953b-f091-486d-ad80-621036ba19d0', 12, 'Seasoned flour', '1 tsp black pepper', 'black pepper', 1, 'tsp', null, false),
