insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6199953b-f091-486d-ad80-621036ba19d0', 1, 'Buttermilk soak', 'Whisk the buttermilk, hot sauce, salt and pepper in a large bowl. Add the chicken, turn to coat, cover and refrigerate at least 4 hours or overnight.', 14400, null, null),
  ('6199953b-f091-486d-ad80-621036ba19d0', 2, 'Seasoned flour', 'Whisk the flour, cornstarch, salt and spices in a wide dish. Drizzle in 3 tablespoons of the buttermilk soak and rub it in with your fingertips so the flour forms small clumps — these become the crunchy bits.', null, null, null),
  ('6199953b-f091-486d-ad80-621036ba19d0', 3, null, 'Lift the chicken out, letting the excess drip off, and press each piece firmly into the flour on all sides. Set on a wire rack for 15 minutes so the coating sets and doesn''t fall off in the oil.', 900, null, null),
  ('6199953b-f091-486d-ad80-621036ba19d0', 4, null, 'Pour the oil into a heavy Dutch oven to a depth of about 1½ inches — never more than half full, so it can''t bubble over — and heat to 340°F. Heat the oven to 200°F and set a wire rack on a sheet pan for draining.', null, 171.1, null),
  ('6199953b-f091-486d-ad80-621036ba19d0', 5, null, 'Deep-fry the dark meat first, 3 or 4 pieces at a time, turning now and then and adjusting the heat to hold the oil at about 325°F, until deep golden and the thickest part reads 165°F: 12–15 minutes for thighs and drumsticks, 10–12 for breast pieces.', 840, 162.8, 73.9),
  ('6199953b-f091-486d-ad80-621036ba19d0', 6, null, 'Drain on the rack and keep warm in the oven while you fry the rest. Rest 5 minutes before serving.', 300, 93.3, null);

-- Classic Meatloaf
