values ('9a2103ae-69a7-4c27-9037-b4306f51be4e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'classic-meatloaf', 'classic-meatloaf-9a2103', 'Classic Meatloaf', 'A tender, well-seasoned beef loaf with a tangy-sweet ketchup glaze, baked free-form so the sides brown.', 'american', 2, 20, 65, 85, 6, 'main', null, 0, array['oven']::text[], array['comfort', 'budget', 'kid-friendly', 'freezer-friendly']::text[], array['Use 85% lean beef: leaner beef makes a dry loaf, and fattier beef leaves a pool of grease.']::text[], 'https://images.pexels.com/photos/34326258/pexels-photo-34326258.jpeg', 'Ketchup-glazed meatloaf with crispy potatoes, coleslaw and a cup of tomato soup', 'Anhelina Vasylyk', 'https://www.pexels.com/@anhelina-vasylyk-734724285/', 'https://www.pexels.com/photo/delicious-meatloaf-with-coleslaw-and-soup-34326258/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'budget', 'main', 'dinner']::text[], array['bake']::text[], array['tangy', 'fresh', 'savory']::text[], '{}'::text[], null, null, 'meatloaf', 'classic', 'Refrigerate up to 4 days, or freeze slices up to 3 months. Leftover slices make great sandwiches.', null, 'owned', array['egg', 'fish', 'gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['dry breadcrumb', 'milk', 'egg', 'worcestershire sauce', 'dried thyme', 'ground beef', 'yellow onion', 'garlic', 'parsley', 'ketchup', 'brown sugar', 'cider vinegar', 'dijon mustard']::text[], 'brown sugar|cider vinegar|dijon mustard|dried thyme|dry breadcrumb|egg|garlic|ground beef|ketchup|milk|parsley|worcestershire sauce|yellow onion',
  null, null, null, null, null, null, null, null)
