insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 1, null, 'Heat the oven to 350°F and line a sheet pan with foil.', null, 176.7, null),
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 2, 'Meatloaf', 'In a large bowl, soak the breadcrumbs in the milk until soft, about 5 minutes. Beat in the eggs, Worcestershire, salt, pepper and thyme.', 300, null, null),
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 3, 'Meatloaf', 'Add the beef, onion, garlic and parsley and mix gently with your hands just until combined — overmixing makes a dense, tough loaf.', null, null, null),
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 4, 'Glaze', 'Shape the mixture into a 9-by-5-inch loaf on the sheet pan. Stir the glaze ingredients together and spread half over the top.', null, null, null),
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 5, null, 'Bake for 45 minutes.', 2700, 176.7, null),
  ('9a2103ae-69a7-4c27-9037-b4306f51be4e', 6, null, 'Spread on the rest of the glaze and bake until an instant-read thermometer in the center reads 160°F, 15–20 minutes more. Rest 10 minutes before slicing.', 1080, 176.7, 71.1);

