insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 1, null, 'Pat the beef dry and season all over with the salt and pepper (an hour ahead if you can). Heat the oven to 300°F.', null, 148.9, null),
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 2, null, 'Heat the oil in a Dutch oven over medium-high heat and brown the roast well on all sides, 10–12 minutes. Move it to a plate.', 720, null, null),
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 3, null, 'Lower the heat to medium. Cook the onions until browned at the edges, 5 minutes, then stir in the garlic, tomato paste and flour for 1 minute. Pour in the wine, if using, and the stock, scraping up the browned bits.', 360, null, null),
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 4, null, 'Return the beef and its juices and add the thyme and bay; the liquid should come about halfway up the meat. Bring to a simmer, cover and braise in the oven for 2 hours.', 7200, 148.9, null),
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 5, null, 'Tuck the potatoes, carrots and parsnips around the beef. Cover and braise until the meat is fork-tender (well past the 145°F safe minimum) and the vegetables are soft, 1–1½ hours more.', 4500, 148.9, 62.8),
  ('d3c04a1b-6899-4588-b51c-28ddc9dc7c61', 6, null, 'Move the beef and vegetables to a platter and tent with foil. Skim the fat off the liquid, discard the thyme and bay, and simmer on the stove until it thickens to a light gravy, about 5 minutes. Slice or pull the beef apart, spoon the gravy over and scatter with parsley.', 300, null, null);

-- Philly Cheesesteak
