values ('2209f8a3-e3ed-4783-8117-5b81c073bf2e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'philly-cheesesteak', 'philly-cheesesteak-2209f8', 'Philly Cheesesteak', 'Thin-shaved ribeye seared on a hot griddle with soft onions, blanketed in melted provolone and scooped into a hoagie roll.', 'american', 2, 50, 15, 65, 4, 'main', null, 0, array['stove', 'cast_iron']::text[], array['comfort']::text[], array['No ribeye? Ask the butcher to shave sirloin or top round, or look for pre-sliced shaved steak in the meat case.', 'For the other Philly classic, skip the provolone and spoon warm cheese sauce over the meat in the roll.']::text[], 'https://images.unsplash.com/photo-1778449736460-9a8f2117571a', 'Cheesesteak hoagie stuffed with chopped steak and melted cheese on a dark background', 'Shoeib Abolhassani', 'https://unsplash.com/@shoeibabhn', 'https://unsplash.com/photos/a-delicious-cheesesteak-sandwich-on-a-dark-background-eMgLVzvKpIM', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday']::text[], array['pan_fry']::text[], '{}'::text[], array['game-day']::text[], 'Philadelphia', 'traditional', 'cheesesteak', 'classic', 'Best right away. Refrigerate the meat and onions (without the roll) up to 3 days and reheat in a hot skillet.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef']::text[], '{}'::text[], array['ribeye steak', 'yellow onion', 'provolone cheese', 'hoagie roll']::text[], 'hoagie roll|provolone cheese|ribeye steak|yellow onion',
  null, null, null, null, null, null, null, null)
