  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 1, null, '2 cups all-purpose flour', 'all-purpose flour', 2, 'cup', null, false),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 2, null, '2 tbsp sugar', 'sugar', 2, 'tbsp', null, false),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 3, null, '1½ tsp baking powder', 'baking powder', 1.5, 'tsp', null, false),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 4, null, '1 tsp baking soda', 'baking soda', 1, 'tsp', null, false),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 5, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
