insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 1, null, 'Whisk the flour, sugar, baking powder, baking soda and salt in a large bowl.', null, null, null),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 2, null, 'In another bowl, whisk the buttermilk, eggs, melted butter and vanilla. Pour into the dry ingredients and stir with a fork just until no dry flour shows — lumps are good. Let the batter rest 5 minutes.', 300, null, null),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 3, null, 'Heat a large skillet or griddle over medium-low heat until a drop of water sizzles, about 3 minutes, and brush with butter.', 180, null, null),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 4, null, 'Pour ¼ cup batter per pancake. Cook until bubbles rise and pop on the surface and the edges look dry, 2–3 minutes.', 180, null, null),
  ('f8cd3840-367f-428f-b9e5-0d600679e6cc', 5, null, 'Flip and cook until golden and springy in the middle, 1–2 minutes more. Keep warm on a plate under a clean towel while you cook the rest, and serve with maple syrup.', 120, null, null);

