values ('376c60f0-9a74-4010-9adf-03eeedb49915', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'new-england-clam-chowder', 'new-england-clam-chowder-376c60', 'New England Clam Chowder', 'Fresh clams, smoky bacon and tender potatoes in a creamy, not-too-thick broth that tastes of the sea.', 'american', 2, 25, 50, 75, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort']::text[], array['Short on time? Use three 6.5-oz cans of chopped clams with their juice plus an extra cup of bottled clam juice, and stir the clams in at the cream stage.', 'Like most chowders, it tastes better after resting an hour or overnight.']::text[], 'https://images.unsplash.com/photo-1718985341774-165fcfc25c71', 'Bowl of creamy clam chowder on a white plate', 'Laura Peruchi', 'https://unsplash.com/@lauraperuchi', 'https://unsplash.com/photos/a-bowl-of-soup-sitting-on-top-of-a-white-plate-DXPRHThRryo', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'comfort', 'main', 'dinner']::text[], array['stew', 'steam', 'boil']::text[], array['rich', 'fresh']::text[], '{}'::text[], 'New England', 'traditional', 'clam-chowder', 'classic', 'Refrigerate up to 2 days and reheat gently without boiling. It doesn''t freeze well — the potatoes turn grainy.', null, 'owned', array['gluten', 'milk', 'shellfish', 'wheat']::text[], array['pork', 'shellfish']::text[], '{}'::text[], array['littleneck clam', 'thick-cut bacon', 'yellow onion', 'celery', 'clam juice', 'gold potato', 'thyme', 'bay leaf', 'milk', 'heavy cream', 'chive']::text[], 'bay leaf|celery|chive|clam juice|gold potato|heavy cream|littleneck clam|milk|thick-cut bacon|thyme|yellow onion',
  null, null, null, null, null, null, null, null)
