insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 1, null, 'Heat the oven to 350°F and butter a 9-by-13-inch baking dish.', null, 176.7, null),
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 2, null, 'Boil the macaroni in well-salted water for 2 minutes less than the package says. Drain, return to the pot and toss with the butter.', 360, null, null),
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 3, null, 'Whisk the evaporated milk, whole milk, eggs, mustard, paprika, cayenne, salt and pepper together.', null, null, null),
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 4, null, 'Set aside 1½ cups of the cheddar for the top. Spread half the macaroni in the dish, scatter over half the remaining cheese, then repeat. Pour the egg mixture evenly over and finish with the reserved cheddar.', null, null, null),
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 5, null, 'Bake uncovered until the custard is set in the center (160°F) and the top is bubbling and browned at the edges, 35–40 minutes.', 2280, 176.7, 71.1),
  ('5e7a0688-e536-4bf9-924f-d0b137081ea6', 6, null, 'Let it rest 10 minutes so it sets and cuts neatly.', 600, null, null);

