  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 1, null, '1½ lb smoked turkey wings', 'smoked turkey wings', 1.5, 'lb', null, false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 2, null, '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 3, null, '1 yellow onion, chopped', 'yellow onion', 1, null, 'chopped', false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 4, null, '4 cloves garlic, sliced', 'garlic', 4, 'clove', 'sliced', false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 5, null, '4 cups water', 'water', 4, 'cup', null, false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 6, null, '2 cups low-sodium chicken stock', 'low-sodium chicken stock', 2, 'cup', null, false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 7, null, '3 bunch collard greens, about 3 lb, stems removed, leaves cut into ribbons', 'collard greens', 3, 'bunch', 'about 3 lb, stems removed, leaves cut into ribbons', false),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 8, null, '2 tbsp apple cider vinegar', 'apple cider vinegar', 2, 'tbsp', null, false),
