insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 1, null, 'Heat the oil in a Dutch oven over medium heat. Cook the onion until soft, about 5 minutes, then add the garlic for 1 minute.', 360, null, null),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 2, null, 'Add the turkey wings, water and stock. Bring to a boil, then cover and simmer until the meat is tender and the broth (the pot likker) tastes smoky, about 1 hour. The turkey should be well above 165°F.', 3600, null, 73.9),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 3, null, 'Meanwhile, wash the collards in a sink of cold water, lifting them out and changing the water until no grit settles at the bottom.', null, null, null),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 4, null, 'Add the greens a few handfuls at a time, stirring as they wilt. Stir in the vinegar, sugar, pepper flakes and salt. Cover and simmer gently, stirring now and then, until silky-tender, 45–60 minutes.', 3000, null, null),
  ('cf9cef42-7045-4b2e-8527-d53974f0164f', 5, null, 'Lift out the turkey, pull the meat from the bones, chop it and stir it back in; discard the skin and bones. Taste for salt and vinegar and serve with plenty of pot likker, and hot pepper vinegar on the side.', null, null, null);

