  ('141c666d-63db-413f-a411-84eeec8f456c', 5, 'Grits', '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('141c666d-63db-413f-a411-84eeec8f456c', 6, 'Grits', '1 cup sharp cheddar cheese, shredded', 'sharp cheddar cheese', 1, 'cup', 'shredded', false),
  ('141c666d-63db-413f-a411-84eeec8f456c', 7, 'Shrimp', '4 slice bacon, diced', 'bacon', 4, 'slice', 'diced', false),
  ('141c666d-63db-413f-a411-84eeec8f456c', 8, 'Shrimp', '1½ lb large shrimp, peeled and deveined', 'large shrimp', 1.5, 'lb', 'peeled and deveined', false),
  ('141c666d-63db-413f-a411-84eeec8f456c', 9, 'Shrimp', '½ tsp smoked paprika', 'smoked paprika', 0.5, 'tsp', null, false),
  ('141c666d-63db-413f-a411-84eeec8f456c', 10, 'Shrimp', '¼ tsp cayenne pepper', 'cayenne pepper', 0.25, 'tsp', null, false),
