values ('9651caa5-2c55-47df-ac29-cf1a72604196', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'biscuits-and-sausage-gravy', 'biscuits-and-sausage-gravy-9651ca', 'Biscuits and Sausage Gravy', 'Flaky, tall buttermilk biscuits split open and smothered in a peppery, creamy pork sausage gravy.', 'southern', 2, 20, 25, 45, 6, 'breakfast', null, 0, array['oven', 'stove']::text[], array['comfort', 'budget']::text[], array['If your sausage is lean and leaves little fat in the pan, add 1–2 tablespoons butter before the flour so the gravy thickens smoothly.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['breakfast', 'comfort', 'holiday', 'budget']::text[], array['stew', 'bake']::text[], array['spicy', 'tangy']::text[], array['brunch-party']::text[], null, 'traditional', 'biscuits-and-gravy', 'classic', 'Biscuits keep 2 days airtight. The gravy keeps 3 days refrigerated; whisk in a splash of milk when reheating.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['baking powder', 'baking soda', 'buttermilk', 'breakfast sausage', 'milk']::text[], 'baking powder|baking soda|breakfast sausage|buttermilk|milk',
  null, null, null, null, null, null, null, null)
