insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 1, 'Biscuits', '2½ cups all-purpose flour, plus more for the counter', 'all-purpose flour', 2.5, 'cup', 'plus more for the counter', false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 2, 'Biscuits', '1 tbsp baking powder', 'baking powder', 1, 'tbsp', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 3, 'Biscuits', '½ tsp baking soda', 'baking soda', 0.5, 'tsp', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 4, 'Biscuits', '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 5, 'Biscuits', '1 tsp sugar', 'sugar', 1, 'tsp', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 6, 'Biscuits', '1 stick cold unsalted butter, cut into cubes', 'cold unsalted butter', 1, 'stick', 'cut into cubes', false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 7, 'Biscuits', '1 cup cold buttermilk', 'cold buttermilk', 1, 'cup', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 8, 'Biscuits', '2 tbsp unsalted butter, melted, for brushing', 'unsalted butter', 2, 'tbsp', 'melted, for brushing', false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 9, 'Gravy', '1 lb bulk pork breakfast sausage', 'bulk pork breakfast sausage', 1, 'lb', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 10, 'Gravy', '⅓ cup all-purpose flour', 'all-purpose flour', 0.33, 'cup', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 11, 'Gravy', '3 cups whole milk', 'whole milk', 3, 'cup', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 12, 'Gravy', '¾ tsp black pepper, coarsely ground, plus more', 'black pepper', 0.75, 'tsp', 'coarsely ground, plus more', false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 13, 'Gravy', '¼ tsp kosher salt', 'kosher salt', 0.25, 'tsp', null, false),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 14, 'Gravy', '1 pinch cayenne pepper', 'cayenne pepper', 1, 'pinch', null, true);
delete from public.recipe_instructions where recipe_id = '9651caa5-2c55-47df-ac29-cf1a72604196';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 1, 'Biscuits', 'Heat the oven to 450°F and line a sheet pan with parchment.', null, 232.2, null),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 2, 'Biscuits', 'Whisk the flour, baking powder, baking soda, salt and sugar. Cut in the cold butter with a pastry blender or your fingertips until pea-sized pieces remain, then stir in the buttermilk with a fork just until a shaggy dough forms.', null, null, null),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 3, 'Biscuits', 'Turn the dough onto a floured counter, pat it 1 inch thick and fold it in thirds like a letter. Pat out and fold twice more, then pat to 1 inch and cut 2½-inch rounds, pressing straight down without twisting. Press the scraps together once to cut a few more.', null, null, null),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 4, 'Biscuits', 'Set the biscuits on the pan just touching each other and bake until tall and golden, 12–15 minutes. Brush with the melted butter.', 780, 232.2, null),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 5, 'Gravy', 'Meanwhile, cook the sausage in a large skillet over medium-high heat, breaking it into small crumbles, until browned with no pink left and it reaches 160°F, about 8 minutes. Don''t drain it.', 480, null, 71.1),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 6, 'Gravy', 'Sprinkle the flour over the sausage and stir for 2 minutes. Slowly stir in the milk and simmer, stirring, until thick and creamy, 5–7 minutes. Season with plenty of pepper, the salt and a pinch of cayenne if you like.', 480, null, null),
  ('9651caa5-2c55-47df-ac29-cf1a72604196', 7, null, 'Split the warm biscuits and ladle the gravy over them.', null, null, null);

