values ('f5ebef10-34dd-4200-b164-5dcfa525e0fd', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'red-beans-and-rice', 'red-beans-and-rice-f5ebef', 'Red Beans and Rice', 'The New Orleans Monday classic: dried red beans simmered for hours with andouille and the trinity until they turn creamy, served over white rice.', 'cajun_creole', 2, 20, 160, 180, 8, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['budget', 'make-ahead', 'freezer-friendly', 'comfort']::text[], array['Dried kidney beans must boil hard for at least 10 minutes to be safe to eat — never cook them only on low heat or in a slow cooker without boiling them first.']::text[], 'https://images.pexels.com/photos/8992843/pexels-photo-8992843.jpeg', 'Saucy red beans with white rice and a side salad on a plate', 'I Own My Food Art', 'https://www.pexels.com/@i-own-my-food-art-76108785/', 'https://www.pexels.com/photo/cooked-rice-with-vegetables-on-white-ceramic-plate-8992843/', 'pexels', true, 'public', false,
  'pending_review', array['budget', 'main', 'dinner', 'comfort']::text[], array['stew', 'pan_fry', 'boil']::text[], array['spicy']::text[], '{}'::text[], 'New Orleans', 'traditional', 'red-beans-and-rice', 'classic', 'Even better the next day. Refrigerate up to 5 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['pork', 'beans']::text[], array['dairy_free']::text[], array['kidney bean', 'andouille sausage', 'yellow onion', 'bell pepper', 'celery', 'garlic', 'bay leave', 'dried thyme', 'cayenne pepper', 'white rice', 'scallion', 'sauce']::text[], 'andouille sausage|bay leave|bell pepper|cayenne pepper|celery|dried thyme|garlic|kidney bean|sauce|scallion|white rice|yellow onion',
  null, null, null, null, null, null, null, null)
