values ('97a4d29c-a302-477c-bb07-3d86340b3eb1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cuban-sandwich', 'cuban-sandwich-97a4d2', 'Cuban Sandwich', 'Mojo-marinated roast pork, ham, Swiss, pickles and mustard pressed in buttered bread until crisp — adapted with a quick-roasted pork tenderloin instead of slow-roasted shoulder, pressed in a skillet.', 'cuban', 2, 20, 40, 60, 4, 'main', null, 0, array['oven', 'stove', 'cast_iron']::text[], array['lunch', 'entertaining']::text[], array['Leftover roast pork from another meal is perfect here — skip the mojo pork steps.', 'If you can''t find Cuban bread, a soft Italian or French loaf with a thin crust is the closest match.']::text[], null, null, null, null, null, null, null, 'public', false,
