insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('97a4d29c-a302-477c-bb07-3d86340b3eb1', 1, 'Mojo pork', 'Mix the orange juice, lime juice, garlic, cumin, oregano, salt and oil. Coat the pork and refrigerate 1–4 hours.', 3600, null, null),
  ('97a4d29c-a302-477c-bb07-3d86340b3eb1', 2, 'Mojo pork', 'Heat the oven to 425°F. Lift the pork out of the marinade, pat dry and roast on a sheet pan until the center reads 145°F, 20–25 minutes. Rest 10 minutes, then slice thinly.', 1320, 218.3, 62.8),
  ('97a4d29c-a302-477c-bb07-3d86340b3eb1', 3, 'Sandwiches', 'Cut the bread into 4 equal lengths and split them. Spread both cut sides with mustard, then layer Swiss, ham, pork, pickles and another slice of Swiss. Butter the outsides.', null, null, null),
  ('97a4d29c-a302-477c-bb07-3d86340b3eb1', 4, 'Sandwiches', 'Heat a large cast-iron skillet over medium heat. Add the sandwiches, weigh them down with a heavy pan and press until the bread is crisp and flat and the cheese melts, 3–4 minutes per side.', 480, null, null),
  ('97a4d29c-a302-477c-bb07-3d86340b3eb1', 5, null, 'Cut each sandwich on the diagonal and serve hot.', null, null, null);

