values ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'cuban-picadillo', 'picadillo-1099ae', 'Picadillo', 'Cuban ground beef simmered with sofrito, tomato, cumin, briny olives and sweet raisins — a cheap, homey weeknight favorite over rice.', 'cuban', 2, 15, 40, 55, 4, 'main', null, 0, array['stove']::text[], array['budget', 'weeknight', 'kid-friendly', 'freezer-friendly']::text[], array['The sweet-and-salty mix of raisins and olives is the point of the dish; if you''re unsure, start with half the raisins.']::text[], 'https://images.pexels.com/photos/13994283/pexels-photo-13994283.jpeg', 'Picadillo with red, green and yellow bell peppers in a pan', 'Keesha''s Kitchen', 'https://www.pexels.com/@keesha-s-kitchen-22731136/', 'https://www.pexels.com/photo/fresh-picadillo-in-pan-left-on-colorful-tea-towel-13994283/', 'pexels', true, 'public', false,
  'pending_review', array['budget', 'main', 'dinner', 'comfort']::text[], array['stew']::text[], array['tangy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'picadillo', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months. Leftovers make a great empanada filling.', null, 'owned', '{}'::text[], array['beef']::text[], array['gluten_free', 'dairy_free']::text[], array['yellow onion', 'bell pepper', 'garlic', 'ground beef', 'ground cumin', 'dried oregano', 'tomato sauce', 'gold potato', 'green olive', 'raisin']::text[], 'bell pepper|dried oregano|garlic|gold potato|green olive|ground beef|ground cumin|raisin|tomato sauce|yellow onion',
  null, null, null, null, null, null, null, null)
