insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', 1, null, 'Heat the oil in a large skillet over medium heat. Cook the onion and pepper until soft, 6–8 minutes, then add the garlic for 1 minute.', 480, null, null),
  ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', 2, null, 'Raise the heat, add the beef and break it up as it cooks until browned with no pink left and it reaches 160°F, about 8 minutes. Spoon off excess fat.', 480, null, 71.1),
  ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', 3, null, 'Stir in the cumin, oregano, salt and pepper. Add the wine, if using, and simmer until mostly gone, about 2 minutes.', 120, null, null),
  ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', 4, null, 'Add the tomato sauce, water, potato, olives, raisins and capers. Cover and simmer gently until the potato is tender and the sauce has thickened, 15–20 minutes.', 1080, null, null),
  ('1099aef6-a25a-459e-ae13-1a1bd54d1cd1', 5, null, 'Taste and adjust the seasoning. Serve over white rice, ideally with black beans and fried sweet plantains.', null, null, null);

