insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 1, 'Sofrito', 'Pulse all the sofrito ingredients in a food processor into a coarse, wet paste.', null, null, null),
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 2, 'Rice', 'Heat the oil in a wide Dutch oven or caldero over medium heat and brown the ham, about 4 minutes. Add ½ cup sofrito and cook until fragrant and most of its liquid has cooked off, about 4 minutes.', 480, null, null),
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 3, 'Rice', 'Stir in the sazón, oregano, tomato sauce, olives and capers for 1 minute. Add the pigeon peas with their liquid, the water, salt and bay leaf and bring to a boil. Taste: the broth should be a little saltier than you''d like.', 180, null, null),
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 4, 'Rice', 'Stir in the rice and boil uncovered until the liquid drops level with the rice, 5–7 minutes.', 360, null, null),
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 5, 'Rice', 'Stir once from the bottom, cover tightly (a sheet of foil under the lid helps), turn the heat to low and cook without stirring until the rice is tender, 25–30 minutes.', 1680, null, null),
  ('1b03cc3f-3d0a-4b1c-9572-697ce757a285', 6, 'Rice', 'Fluff by turning the rice from the bottom up and remove the bay leaf. For a crispy layer of pegao, leave the pot on medium-low for 5–10 minutes more before serving.', 300, null, null);

