insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 1, 'Chili gravy', '3 tbsp vegetable oil', 'vegetable oil', 3, 'tbsp', null, false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 2, 'Chili gravy', '3 tbsp all-purpose flour', 'all-purpose flour', 3, 'tbsp', null, false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 3, 'Chili gravy', '3 tbsp chili powder, a mild blend', 'chili powder', 3, 'tbsp', 'a mild blend', false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 4, 'Chili gravy', '1 tsp ground cumin', 'ground cumin', 1, 'tsp', null, false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 5, 'Chili gravy', '1 tsp garlic powder', 'garlic powder', 1, 'tsp', null, false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 6, 'Chili gravy', '1 tsp dried Mexican oregano', 'dried Mexican oregano', 1, 'tsp', null, false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 7, 'Chili gravy', '2 cups vegetable stock', 'vegetable stock', 2, 'cup', null, false),
