  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 10, 'Enchiladas', '2 tbsp vegetable oil, for softening the tortillas', 'vegetable oil', 2, 'tbsp', 'for softening the tortillas', false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 11, 'Enchiladas', '12 oz mild cheddar cheese, shredded (about 3 cups)', 'mild cheddar cheese', 12, 'oz', 'shredded (about 3 cups)', false),
  ('cad94a0d-ed99-42e8-bb6a-2200a9ed10f3', 12, 'Enchiladas', '1 yellow onion, finely chopped', 'yellow onion', 1, null, 'finely chopped', false);
