values ('b8b2e718-d3c4-4c05-a781-ecb8bdb3aac2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-enchiladas-verdes', 'chicken-enchiladas-verdes-b8b2e7', 'Chicken Enchiladas Verdes', 'Softened corn tortillas dipped in a tangy tomatillo-serrano salsa, rolled around tender shredded chicken and finished with crema and queso fresco.', 'mexican', 2, 25, 40, 65, 4, 'main', null, 0, array['stove', 'blender']::text[], array['comfort', 'entertaining']::text[], array['Prefer a casserole? Arrange the rolled enchiladas in a baking dish, cover with the salsa and bake at 375°F for 15 minutes, then add the toppings.']::text[], 'https://images.pexels.com/photos/36429905/pexels-photo-36429905.jpeg', 'Enchiladas in green sauce topped with crema and fresh cilantro', 'Willians Huerta', 'https://www.pexels.com/@willians-huerta-2157111846/', 'https://www.pexels.com/photo/delicious-green-enchiladas-with-creamy-garnish-36429905/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['stew']::text[], array['spicy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'enchiladas-verdes', 'classic', 'Best fresh — the tortillas soften as they sit. Keep extra chicken and salsa separately up to 4 days in the fridge.', null, 'owned', array['milk']::text[], array['chicken']::text[], array['gluten_free']::text[], array['white onion', 'garlic', 'bay leaf', 'tomatillo', 'serrano chile', 'cilantro', 'corn tortilla', 'mexican crema', 'queso fresco']::text[], 'bay leaf|cilantro|corn tortilla|garlic|mexican crema|queso fresco|serrano chile|tomatillo|white onion',
  null, null, null, null, null, null, null, null)
