  ('549a30bd-5320-4145-88a5-9d9661c2978a', 10, 'Toppings', '1 tbsp vegetable oil', 'vegetable oil', 1, 'tbsp', null, false),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 11, 'Toppings', '½ cup queso fresco, crumbled', 'queso fresco', 0.5, 'cup', 'crumbled', false),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 12, 'Toppings', '¼ cup Mexican crema, or sour cream', 'Mexican crema', 0.25, 'cup', 'or sour cream', false),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 13, 'Toppings', '¼ white onion, thinly sliced', 'white onion', 0.25, null, 'thinly sliced', false),
  ('549a30bd-5320-4145-88a5-9d9661c2978a', 14, 'Toppings', '¼ cup fresh cilantro leaves', 'fresh cilantro leaves', 0.25, 'cup', null, false),
