insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('47e0f20c-eb56-4307-b4fe-1aa4179af0cc', 1, null, 'In a molcajete or a sturdy bowl, mash 1 tablespoon of the onion, half the chile, a little of the cilantro and the salt into a rough paste.', null, null, null),
  ('47e0f20c-eb56-4307-b4fe-1aa4179af0cc', 2, null, 'Halve and pit the avocados, scoop them in and mash coarsely with a fork or pestle, leaving some chunks.', null, null, null),
  ('47e0f20c-eb56-4307-b4fe-1aa4179af0cc', 3, null, 'Fold in the rest of the onion, chile and cilantro, the lime juice and the tomato, if using. Taste and adjust the salt and lime.', null, null, null),
  ('47e0f20c-eb56-4307-b4fe-1aa4179af0cc', 4, null, 'Serve right away with tortilla chips or alongside tacos.', null, null, null);

