values ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pollo-a-la-brasa', 'pollo-a-la-brasa-c35aea', 'Pollo a la Brasa', 'Peru''s beloved rotisserie chicken, marinated in soy, lime, garlic, cumin and ají panca and served with a creamy green ají sauce — adapted to roast in a hot oven instead of over charcoal.', 'peruvian', 2, 25, 75, 100, 4, 'main', null, 0, array['oven', 'blender']::text[], array['entertaining', 'kid-friendly']::text[], array['Ají panca and ají amarillo are Peruvian chile pastes sold in jars in Latin markets; ancho chile powder and an extra seeded jalapeño are good stand-ins.']::text[], 'https://images.pexels.com/photos/34110277/pexels-photo-34110277.jpeg', 'Peruvian rotisserie chicken with fries, salad and dipping sauces seen from above', 'Arti.tic', 'https://www.pexels.com/@arti-tic-1675363189/', 'https://www.pexels.com/photo/delicious-peruvian-rotisserie-chicken-meal-top-view-34110277/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort', 'entertaining']::text[], array['roast']::text[], array['spicy', 'tangy', 'fresh', 'savory', 'aromatic']::text[], '{}'::text[], 'Lima', 'adapted', 'pollo-a-la-brasa', 'classic', 'Refrigerate the chicken up to 3 days and the sauce up to 4 days.', null, 'owned', array['egg', 'gluten', 'milk', 'soy', 'wheat']::text[], array['chicken']::text[], '{}'::text[], array['chicken', 'soy sauce', 'lime juice', 'garlic', 'panca paste', 'ground cumin', 'paprika', 'dried oregano', 'cilantro', 'jalapeno chile', 'mayonnaise', 'queso fresco']::text[], 'chicken|cilantro|dried oregano|garlic|ground cumin|jalapeno chile|lime juice|mayonnaise|panca paste|paprika|queso fresco|soy sauce',
  null, null, null, null, null, null, null, null)
