delete from public.recipe_instructions where recipe_id = 'c35aea42-7d32-4fa7-a2a5-436274f37d5e';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', 1, 'Chicken', 'Whisk the soy sauce, lime juice, oil, garlic, ají panca, cumin, paprika, oregano, salt and pepper into a paste. Loosen the skin over the breast and thighs with your fingers and rub the paste under and over the skin. Refrigerate at least 4 hours or overnight.', 14400, null, null),
  ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', 2, 'Chicken', 'Heat the oven to 425°F. Set the chicken breast-side up on a rack in a roasting pan, tuck the wing tips under and tie the legs together.', null, 218.3, null),
  ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', 3, 'Chicken', 'Roast until the skin is deep mahogany and an instant-read thermometer in the thickest part of the thigh (not touching bone) reads 165°F, 60–75 minutes. Cover loosely with foil if it darkens too fast.', 4200, 218.3, 73.9),
  ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', 4, 'Green sauce', 'Meanwhile, blend all the green sauce ingredients until smooth. Taste for salt and heat, and refrigerate until serving.', null, null, null),
  ('c35aea42-7d32-4fa7-a2a5-436274f37d5e', 5, null, 'Rest the chicken 10 minutes, carve into quarters and serve with the green sauce, fries and a simple salad.', 600, null, null);

