values ('471981de-a9cd-4383-92b9-dc7e50e4fa98', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'arepas-black-beans-cheese', 'arepas-471981', 'Arepas', 'Golden griddled corn cakes, crisp outside and steamy-soft inside, split and stuffed with cumin-spiced black beans and fresh cheese — the bean-and-cheese filling borrows from the Venezuelan dómino.', 'colombian', 2, 20, 30, 50, 4, 'starter', null, 0, array['stove', 'cast_iron']::text[], array['vegetarian', 'kid-friendly', 'budget']::text[], array['Masarepa is precooked corn flour sold in the Latin aisle. Masa harina and ordinary cornmeal won''t work here.']::text[], 'https://images.pexels.com/photos/29496090/pexels-photo-29496090.jpeg', 'Golden arepas with avocado and salsa on a wooden board', 'Nano Erdozain', 'https://www.pexels.com/@nano-erdozain-120534369/', 'https://www.pexels.com/photo/delicious-arepas-with-avocado-and-salsa-29496090/', 'pexels', true, 'public', false,
  'pending_review', array['appetizer', 'budget', 'comfort']::text[], array['stew']::text[], array['aromatic']::text[], '{}'::text[], null, 'adapted', 'arepas', 'classic', 'Cooked, unfilled arepas keep 3 days refrigerated or 2 months frozen; reheat in a dry skillet.', null, 'owned', array['milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['masarepa', 'yellow onion', 'garlic', 'ground cumin', 'black bean', 'queso fresco']::text[], 'black bean|garlic|ground cumin|masarepa|queso fresco|yellow onion',
  null, null, null, null, null, null, null, null)
