insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('471981de-a9cd-4383-92b9-dc7e50e4fa98', 1, 'Arepas', 'Mix the masarepa and salt in a bowl, then stir in the warm water and melted butter. Knead 1–2 minutes into a smooth, soft dough, cover and rest 5 minutes. If it cracks when pressed, work in more water a tablespoon at a time.', 300, null, null),
  ('471981de-a9cd-4383-92b9-dc7e50e4fa98', 2, 'Arepas', 'Divide into 8 balls and flatten each between your palms into a round about ½ inch thick and 3½ inches across, smoothing any cracked edges.', null, null, null),
  ('471981de-a9cd-4383-92b9-dc7e50e4fa98', 3, 'Filling', 'Heat the oil in a small saucepan over medium heat and cook the onion until soft, about 5 minutes. Add the garlic and cumin for 30 seconds, then the beans, water and salt. Simmer 5 minutes, mashing about half the beans.', 600, null, null),
  ('471981de-a9cd-4383-92b9-dc7e50e4fa98', 4, 'Arepas', 'Heat a cast-iron skillet over medium heat with a thin film of oil. Cook the arepas in batches until a golden crust forms on each side and they sound hollow when tapped, 6–8 minutes per side.', 840, null, null),
  ('471981de-a9cd-4383-92b9-dc7e50e4fa98', 5, null, 'Split each warm arepa partway open with a knife, like a pita pocket, stuff with beans and cheese and serve hot.', null, null, null);

