values ('b13ed2d0-bb4c-48e7-b6a8-42bc4feaf982', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pupusas-beans-cheese-curtido', 'pupusas-b13ed2', 'Pupusas', 'Salvadoran masa cakes stuffed with refried beans and melty cheese, cooked on a hot griddle and served with tangy, oregano-scented curtido.', 'salvadoran', 2, 40, 25, 125, 4, 'main', null, 60, array['stove', 'cast_iron']::text[], array['budget', 'vegetarian']::text[], array['Quesillo is a soft, stretchy Salvadoran melting cheese; a mix of mozzarella and Monterey Jack is a good substitute.', 'Check the label on the refried beans — some brands are made with lard.']::text[], 'https://images.pexels.com/photos/33490827/pexels-photo-33490827.jpeg', 'Griddled pupusa topped with guacamole, with side dishes on the table', 'Urian Rivera', 'https://www.pexels.com/@urianrivera/', 'https://www.pexels.com/photo/delicious-pupusa-with-guacamole-on-dining-table-33490827/', 'pexels', true, 'public', false,
  'pending_review', array['budget', 'main', 'dinner']::text[], array['boil']::text[], array['spicy', 'tangy']::text[], '{}'::text[], null, 'traditional', 'pupusas', 'classic', 'Curtido keeps 1 week refrigerated. Cooked pupusas freeze well up to 2 months; reheat in a dry skillet.', null, 'owned', array['milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['green cabbage', 'carrot', 'white onion', 'cider vinegar', 'mexican oregano', 'masa harina', 'refried bean', 'mozzarella cheese']::text[], 'carrot|cider vinegar|green cabbage|masa harina|mexican oregano|mozzarella cheese|refried bean|white onion',
  null, null, null, null, null, null, null, null)
