values ('795104f8-2338-4a89-8191-d23a37d95782', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'poutine', 'poutine-795104', 'Poutine', 'Crisp fries topped with squeaky cheese curds and hot, peppery beef gravy that softens the curds just enough — adapted with oven fries instead of double-frying.', 'canadian', 1, 20, 45, 65, 4, 'main', null, 0, array['oven', 'stove']::text[], array['comfort', 'kid-friendly']::text[], array['Fresh curds should squeak when you bite them; look for them near the deli cheeses. Torn fresh mozzarella is the best stand-in.']::text[], 'https://images.pexels.com/photos/15159417/pexels-photo-15159417.jpeg', 'Bowl of poutine with fries, cheese and gravy beside a glass of beer', 'MikeGz', 'https://www.pexels.com/@mikegz-400576129/', 'https://www.pexels.com/photo/food-in-bowl-15159417/', 'pexels', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'holiday']::text[], array['roast', 'stew']::text[], array['tangy']::text[], array['canada-day']::text[], 'Québec', 'adapted', 'poutine', 'classic', 'Poutine doesn''t keep — assemble it just before eating. Leftover gravy keeps 4 days refrigerated.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], '{}'::text[], array['russet potato', 'shallot', 'beef stock', 'cider vinegar', 'cheese curd']::text[], 'beef stock|cheese curd|cider vinegar|russet potato|shallot',
  null, null, null, null, null, null, null, null)
