values ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lasagna-bolognese', 'classic-lasagna-bolognese-337ba1', 'Classic Lasagna Bolognese', 'Slow-simmered beef and pork ragù layered with silky béchamel and Parmigiano; we use dried lasagna sheets in place of the fresh egg pasta used in Bologna.', 'italian', 3, 45, 195, 240, 8, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'freezer-friendly', 'entertaining']::text[], array['Make the ragù a day ahead: it tastes better and the lasagna comes together in 30 minutes.', 'No-boil lasagna sheets work too; add ½ cup extra water to the ragù so they have liquid to absorb.']::text[], 'https://images.unsplash.com/photo-1730900737654-ac6d843139da', 'Slice of baked lasagna with tomato sauce and melted cheese on a black plate', 'Ömer Taha Çetin', 'https://unsplash.com/@omertahacetin', 'https://unsplash.com/photos/a-black-plate-topped-with-lasagna-covered-in-sauce-and-cheese-Tl6IYQse-tc', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'entertaining']::text[], array['stew', 'pan_fry', 'bake', 'boil']::text[], array['savory']::text[], '{}'::text[], 'Emilia-Romagna', 'adapted', 'lasagna-bolognese', 'classic', 'Refrigerate up to 4 days or freeze, well wrapped, up to 3 months. Reheat covered at 350°F until hot in the middle.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['beef', 'pork']::text[], '{}'::text[], array['pancetta', 'yellow onion', 'carrot', 'celery', 'ground beef', 'ground pork', 'white wine', 'tomato paste', 'tomato passata', 'milk', 'ground nutmeg', 'lasagna sheet', 'parmigiano-reggiano']::text[], 'carrot|celery|ground beef|ground nutmeg|ground pork|lasagna sheet|milk|pancetta|parmigiano-reggiano|tomato passata|tomato paste|white wine|yellow onion',
  null, null, null, null, null, null, null, null)
