  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 15, 'Béchamel', '½ cup all-purpose flour', 'all-purpose flour', 0.5, 'cup', null, false),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 16, 'Béchamel', '4 cups whole milk', 'whole milk', 4, 'cup', null, false),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 17, 'Béchamel', '¼ tsp ground nutmeg', 'ground nutmeg', 0.25, 'tsp', null, false),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 18, 'Béchamel', '¾ tsp kosher salt', 'kosher salt', 0.75, 'tsp', null, false),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 19, 'Assembly', '12 oz dried lasagna sheets, about 16 sheets', 'dried lasagna sheets', 12, 'oz', 'about 16 sheets', false),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 20, 'Assembly', '1½ cups Parmigiano-Reggiano, finely grated', 'Parmigiano-Reggiano', 1.5, 'cup', 'finely grated', false);
delete from public.recipe_instructions where recipe_id = '337ba1a3-d080-49a9-bc60-de2636a9ea6a';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 1, 'Ragù', 'Warm the oil in a Dutch oven over medium heat and cook the pancetta until the fat runs, 3 minutes. Add the onion, carrot and celery and cook gently until soft and sweet, 10 minutes.', 780, null, null),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 2, 'Ragù', 'Raise the heat, add the beef and pork and cook, breaking it up, until no pink remains and the meat reaches 160°F, about 8 minutes.', 480, null, 71.1),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 3, 'Ragù', 'Pour in the wine and let it bubble away. Stir in the tomato paste, passata, milk, water and salt. Simmer uncovered on the lowest heat, stirring now and then, until thick and glossy, about 2 hours; add a splash of water if it catches.', 7200, null, null),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 4, 'Béchamel', 'Melt the butter in a saucepan, whisk in the flour and cook 2 minutes without browning. Whisk in the milk a little at a time, then simmer, whisking, until it coats a spoon, 8–10 minutes. Season with the nutmeg and salt.', 600, null, null),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 5, 'Assembly', 'Heat the oven to 375°F. Boil the lasagna sheets in well-salted water for 2 minutes less than the package says, then lay them flat on an oiled sheet pan.', 480, 190.6, null),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 6, 'Assembly', 'In a 9-by-13-inch baking dish, spread a thin layer of béchamel, then repeat layers of pasta, ragù, béchamel and Parmigiano (about 5 layers), finishing with béchamel and cheese.', null, null, null),
  ('337ba1a3-d080-49a9-bc60-de2636a9ea6a', 7, 'Assembly', 'Bake until bubbling and browned on top, 35–40 minutes. Rest 20 minutes before cutting so the layers hold.', 2280, 190.6, null);

-- Cacio e Pepe
insert into public.recipes (id, source_id, external_id, slug, title, description, cuisine, skill_level, prep_minutes, cook_minutes, total_minutes, servings, course, dessert_category, chill_minutes, required_equipment, tags, tips, image_url, image_alt, image_credit, image_credit_url, image_source_url, image_license, image_is_representative, visibility, is_mock,
