insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 1, null, 'Bring 3 quarts of water to a boil with the salt — less water than usual, so it gets starchy.', null, null, null),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 2, null, 'Toast the cracked pepper in a large dry skillet over medium heat until fragrant, about 1 minute, then take the pan off the heat.', 60, null, null),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 3, null, 'Cook the pasta until 2 minutes short of al dente. Meanwhile, stir ½ cup of the hot pasta water into the pepper pan and let it cool slightly.', 540, null, null),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 4, null, 'In a bowl, mash the Pecorino with about ⅓ cup warm (not boiling) pasta water into a smooth, thick paste.', null, null, null),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 5, null, 'Move the pasta into the skillet with tongs and toss over low heat for 1–2 minutes until the water in the pan is mostly absorbed. Take it off the heat.', 120, null, null),
  ('dc595d25-0ab6-4227-923b-f0c7504d964e', 6, null, 'Add the cheese paste and toss hard, adding pasta water a spoonful at a time, until the sauce is creamy and clings to every strand. Serve at once with more pepper.', null, null, null);

-- Pasta all'Amatriciana
