values ('6008140d-3544-4161-a58e-1f3dafcf3a5e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pasta-amatriciana', 'pasta-all-amatriciana-600814', 'Pasta all''Amatriciana', 'Crisp guanciale, its rendered fat, tomatoes, chili and sharp Pecorino — no onion or garlic, as they make it in Amatrice.', 'italian', 2, 10, 30, 40, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'pantry']::text[], array['Guanciale (cured pork jowl) is sold at Italian delis; pancetta is the closest supermarket swap, and thick-cut unsmoked bacon will do in a pinch.']::text[], 'https://images.pexels.com/photos/37180268/pexels-photo-37180268.jpeg', 'Bowl of rigatoni in tomato sauce with crisp cured pork and grated cheese', 'Max Griss', 'https://www.pexels.com/@max-griss-16866522/', 'https://www.pexels.com/photo/delicious-rigatoni-pasta-with-parmesan-cheese-37180268/', 'pexels', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stew', 'boil']::text[], array['spicy']::text[], '{}'::text[], 'Lazio', 'traditional', 'amatriciana', 'classic', 'Refrigerate the sauce up to 4 days; cook fresh pasta to serve.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], array['pork']::text[], '{}'::text[], array['guanciale', 'white wine', 'canned tomato', 'pepper flake', 'bucatini', 'romano cheese']::text[], 'bucatini|canned tomato|guanciale|pepper flake|romano cheese|white wine',
  null, null, null, null, null, null, null, null)
