  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 3, null, '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 4, null, '6 oz thick-cut bacon, cut into ½-inch pieces', 'thick-cut bacon', 6, 'oz', 'cut into ½-inch pieces', false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 5, null, '2 tbsp all-purpose flour', 'all-purpose flour', 2, 'tbsp', null, false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 6, null, '1 yellow onion, chopped', 'yellow onion', 1, null, 'chopped', false),
