  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 9, null, '1 tbsp tomato paste', 'tomato paste', 1, 'tbsp', null, false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 10, null, '750 ml dry red wine, Burgundy or Pinot Noir', 'dry red wine', 750, 'ml', 'Burgundy or Pinot Noir', false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 11, null, '1 cup chicken stock', 'chicken stock', 1, 'cup', null, false),
  ('80922e59-bd5e-40ff-a95c-d7a8cf608406', 12, null, '4 sprigs fresh thyme', 'fresh thyme', 4, 'sprig', null, false),
