values ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'french-onion-soup', 'french-onion-soup-36df96', 'French Onion Soup', 'Onions cooked low and slow until deeply caramelized, simmered in beef stock and topped with toasted baguette under a blanket of bubbling Gruyère.', 'french', 2, 20, 100, 120, 4, 'starter', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'entertaining']::text[], array['Don''t rush the onions with high heat — slow browning is the whole flavour of the soup.', 'No ovenproof bowls? Melt the cheese onto the toasts under the broiler and float them on the soup.']::text[], 'https://images.unsplash.com/photo-1741318714411-fad939b8580a', 'Bowl of French onion soup topped with melted cheese', 'Meg von Haartman', 'https://unsplash.com/@traveleroohlala', 'https://unsplash.com/photos/french-onion-soup-with-melted-cheese-NAkk8r6aYfo', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'appetizer', 'comfort', 'entertaining']::text[], array['stew']::text[], '{}'::text[], '{}'::text[], 'Paris', 'traditional', 'french-onion-soup', 'classic', 'Refrigerate the soup (without bread and cheese) up to 4 days or freeze up to 3 months.', null, 'owned', array['gluten', 'milk', 'wheat']::text[], '{}'::text[], '{}'::text[], array['yellow onion', 'white wine', 'beef stock', 'thyme', 'bay leaf', 'baguette', 'gruyere cheese']::text[], 'baguette|bay leaf|beef stock|gruyere cheese|thyme|white wine|yellow onion',
  null, null, null, null, null, null, null, null)
