  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 1, null, '3 lb yellow onions, halved and thinly sliced', 'yellow onions', 3, 'lb', 'halved and thinly sliced', false),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 2, null, '3 tbsp unsalted butter', 'unsalted butter', 3, 'tbsp', null, false),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 3, null, '1 tbsp olive oil', 'olive oil', 1, 'tbsp', null, false),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 4, null, '1 tsp kosher salt', 'kosher salt', 1, 'tsp', null, false),
  ('36df9616-7e74-4f27-9c37-8ff2c3b002e8', 5, null, '1 tbsp all-purpose flour', 'all-purpose flour', 1, 'tbsp', null, false),
