  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 5, null, '1½ cups heavy cream', 'heavy cream', 1.5, 'cup', null, false),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 6, null, '½ cup whole milk', 'whole milk', 0.5, 'cup', null, false),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 7, null, '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
