insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 1, null, 'Heat the oven to 375°F. Fit the crust into a 9-inch pie plate, crimp the edge and chill 15 minutes.', 900, 190.6, null),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 2, null, 'Line the crust with parchment, fill with pie weights or dried beans and bake 20 minutes. Remove the weights and bake until the base looks dry and pale golden, 5–8 minutes more.', 1620, 190.6, null),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 3, null, 'Meanwhile, cook the bacon over medium heat until browned but not hard, 8 minutes. Drain on paper towels.', 480, null, null),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 4, null, 'Lower the oven to 325°F. Whisk the eggs, yolks, cream, milk, salt, pepper and nutmeg until smooth.', null, 162.8, null),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 5, null, 'Scatter the bacon over the warm crust, set the plate on a sheet pan and pour in the custard.', null, null, null),
  ('ced05ff4-4800-47ad-b007-f6924a6562f6', 6, null, 'Bake until the edges are set and the center has a slight wobble and reads 160°F, 35–40 minutes. Cool at least 20 minutes before slicing.', 2280, 162.8, 71.1);

