values ('60a0284c-98c8-45af-aabc-76c50b174782', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'creme-brulee', 'creme-brulee-60a028', 'Crème Brûlée', 'A cool, silky vanilla custard under a thin sheet of caramelized sugar that cracks under your spoon.', 'french', 3, 20, 45, 305, 4, 'dessert', 'plated', 240, array['oven', 'stove']::text[], array['make-ahead', 'entertaining']::text[], array['No torch? Broil the chilled custards on the top rack for 2–4 minutes, watching closely and turning the pan.']::text[], 'https://images.unsplash.com/photo-1779094543236-6c64b71ae14e', 'Crème brûlée with a caramelized sugar top and mint garnish on a blue napkin', 'Tommaso Ubezio', 'https://unsplash.com/@tommasoubezio', 'https://unsplash.com/photos/creme-brulee-with-mint-garnish-on-a-blue-napkin-EIiS4WcsSGA', 'unsplash', true, 'public', false,
  'pending_review', array['dessert', 'baking', 'holiday', 'entertaining']::text[], array['roast', 'steam', 'bake', 'boil']::text[], array['rich', 'sweet']::text[], array['valentines', 'date-night', 'dinner-party']::text[], null, 'traditional', 'creme-brulee', 'classic', 'Keep the baked custards covered in the fridge up to 3 days; caramelize just before serving.', null, 'owned', array['egg', 'milk']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'gluten_free']::text[], array['heavy cream', 'vanilla bean', 'egg yolk']::text[], 'egg yolk|heavy cream|vanilla bean',
  null, null, null, null, null, null, null, null)
