insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('5fc55885-9d3c-4053-afab-38a148fda116', 1, null, 'Toss the grated cucumber with ½ tsp salt in a sieve and leave 10 minutes. Squeeze out as much liquid as you can with your hands or a clean towel.', 600, null, null),
  ('5fc55885-9d3c-4053-afab-38a148fda116', 2, null, 'Stir the garlic into the vinegar and let it stand a few minutes to soften its bite.', null, null, null),
  ('5fc55885-9d3c-4053-afab-38a148fda116', 3, null, 'Mix the yogurt, cucumber, garlic and vinegar, olive oil, dill and remaining salt.', null, null, null),
  ('5fc55885-9d3c-4053-afab-38a148fda116', 4, null, 'Chill at least 30 minutes so the flavours come together. Serve drizzled with olive oil, with pita, vegetables or souvlaki.', 1800, null, null);

