values ('699b9488-3cd1-485d-846a-d8fae1e05b70', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'fish-and-chips', 'fish-and-chips-699b94', 'Fish and Chips', 'Flaky cod in a crisp, puffy beer batter with twice-fried chips, served with malt vinegar and lemon — the chip-shop classic at home.', 'british', 2, 40, 35, 75, 4, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'kid-friendly']::text[], array['Mix the batter just before frying; the cold liquid and fresh bubbles are what make it light.', 'Haddock or pollock are traditional alternatives to cod. Let the oil cool completely before straining and storing or discarding it.']::text[], 'https://images.unsplash.com/photo-1764397557799-258db31fe6a4', 'Battered fried fish and chips with a lemon wedge and dipping sauce', 'Tomi Saputra', 'https://unsplash.com/@udatommo', 'https://unsplash.com/photos/fish-and-chips-with-lemon-and-sauce-on-a-plate-faHiAEp7YvA', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['fry']::text[], array['tangy']::text[], '{}'::text[], null, 'traditional', 'fish-and-chips', 'classic', 'Best eaten immediately. Re-crisp leftovers on a rack at 400°F for 8–10 minutes.', null, 'owned', array['fish', 'gluten', 'wheat']::text[], array['fish']::text[], array['pescatarian', 'dairy_free']::text[], array['russet potato', 'cod fillet', 'baking powder', 'lager beer', 'lemon', 'malt vinegar']::text[], 'baking powder|cod fillet|lager beer|lemon|malt vinegar|russet potato',
  null, null, null, null, null, null, null, null)
