insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 1, 'Chips', 'Rinse the potato sticks in cold water until it runs clear, then soak 30 minutes. Drain and dry very thoroughly on towels.', 1800, null, null),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 2, 'Chips', 'Heat the oil to 325°F in a large heavy pot, filled no more than halfway, with a thermometer clipped to the side. Keep children and pets away and never leave hot oil unattended.', null, 162.8, null),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 3, 'Chips', 'Fry the potatoes in 2 batches until soft and pale but not browned, 5–6 minutes per batch. Drain on a rack.', 720, 162.8, null),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 4, null, 'Raise the oil to 375°F. Pat the fish dry and season lightly. Whisk 1 cup flour, the baking powder and salt, then whisk in the cold beer until just smooth, like thick cream.', null, 190.6, null),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 5, 'Fish', 'Dust each piece of fish in the remaining flour, dip in the batter and lower it into the oil away from you. Fry 2 pieces at a time, turning once, until deep golden and the fish flakes and reads 145°F, 5–7 minutes. Drain on a rack.', 720, 190.6, 62.8),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 6, 'Chips', 'Return the chips to the 375°F oil in batches until crisp and golden, 2–3 minutes. Drain and salt right away.', 300, 190.6, null),
  ('699b9488-3cd1-485d-846a-d8fae1e05b70', 7, null, 'Serve the fish and chips at once with lemon wedges, malt vinegar and flaky salt.', null, null, null);

