values ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'baba-ghanoush', 'baba-ghanoush-29e7fc', 'Baba Ghanoush', 'Eggplant charred until it collapses, then chopped with tahini, lemon and garlic into a smoky, creamy dip.', 'middle_eastern', 1, 15, 35, 50, 6, 'starter', null, 0, array['oven']::text[], array['vegan', 'make-ahead', 'entertaining']::text[], array['An open flame or grill gives the deepest smoky flavour; the broiler comes close.', 'A few flecks of charred skin left in the dip add smokiness — just don''t add whole pieces.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'grilling', 'entertaining']::text[], array['grill']::text[], array['smoky', 'tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'baba-ghanoush', 'classic', 'Refrigerate up to 4 days; it tastes even better the next day.', null, 'owned', array['sesame']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['globe eggplant', 'tahini', 'lemon', 'garlic', 'parsley']::text[], 'garlic|globe eggplant|lemon|parsley|tahini',
  null, null, null, null, null, null, null, null)
