delete from public.recipe_instructions where recipe_id = '29e7fc42-3f0e-40b7-9bb8-be2c936735e8';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', 1, null, 'Prick the eggplants all over with a fork. Char them directly over a gas flame or on a hot grill, or under the broiler about 4 inches from the heat, turning every 5–10 minutes, until the skin is blackened and the eggplants have collapsed completely, 30–40 minutes.', 2100, null, null),
  ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', 2, null, 'Set them in a colander for 15 minutes to cool and let the bitter juices drain.', 900, null, null),
  ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', 3, null, 'Split the eggplants, scoop out the flesh and discard the skin. Let the flesh drain 5 minutes more, then chop it with a knife into a rough pulp — don''t purée it.', 300, null, null),
  ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', 4, null, 'Stir in the tahini, lemon juice, garlic and salt. Taste and add more lemon or salt until it''s bright and smoky.', 180, null, null),
  ('29e7fc42-3f0e-40b7-9bb8-be2c936735e8', 5, null, 'Spread in a shallow bowl, swirl the olive oil over the top and finish with parsley and smoked paprika.', 120, null, null);

