values ('7308482d-f679-4a97-99a1-d02562573d24', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tabbouleh', 'tabbouleh-730848', 'Tabbouleh', 'A bright, lemony Lebanese salad that''s mostly finely sliced parsley and mint, with just a little bulgur and tomato.', 'lebanese', 1, 40, 0, 40, 4, 'side', null, 0, '{}'::text[], array['vegan', 'entertaining']::text[], array['This is a herb salad with a little grain, not a grain salad — resist adding more bulgur.', 'Coarser bulgur needs a 15-minute soak in hot water first; drain it well before adding the tomatoes.']::text[], 'https://images.unsplash.com/photo-1786174044919-c2119725afa1', 'Bowl of parsley tabbouleh with chopped tomatoes and lemon slices on wood', 'Chez Le Libanais', 'https://unsplash.com/@chezlelibanais', 'https://unsplash.com/photos/tabbouleh-salad-with-tomatoes-and-lemon-m5YZbsHYeWk', 'unsplash', true, 'public', false,
  'pending_review', array['salad', 'side', 'entertaining']::text[], array['no_cook']::text[], array['fresh', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'tabbouleh', 'classic', 'Best the day it''s made. Leftovers keep 1 day refrigerated, though the herbs soften.', null, 'owned', array['gluten', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['bulgur', 'tomato', 'lemon', 'flat-leaf parsley', 'mint leave', 'scallion', 'ground allspice']::text[], 'bulgur|flat-leaf parsley|ground allspice|lemon|mint leave|scallion|tomato',
  null, null, null, null, null, null, null, null)
