  ('44575bce-3db0-487e-b573-554c31f11535', 1, null, '2 tbsp olive oil', 'olive oil', 2, 'tbsp', null, false),
  ('44575bce-3db0-487e-b573-554c31f11535', 2, null, '1 tbsp unsalted butter', 'unsalted butter', 1, 'tbsp', null, false),
  ('44575bce-3db0-487e-b573-554c31f11535', 3, null, '3 Turkish green peppers, sliced; or 2 Anaheim or cubanelle peppers', 'Turkish green peppers', 3, null, 'sliced; or 2 Anaheim or cubanelle peppers', false),
  ('44575bce-3db0-487e-b573-554c31f11535', 4, null, '1 onion, finely chopped', 'onion', 1, null, 'finely chopped', true),
  ('44575bce-3db0-487e-b573-554c31f11535', 5, null, '4 ripe tomatoes, about 1½ lb, grated on a box grater, skins discarded', 'ripe tomatoes', 4, null, 'about 1½ lb, grated on a box grater, skins discarded', false),
  ('44575bce-3db0-487e-b573-554c31f11535', 6, null, '1 tsp Aleppo pepper (pul biber), or ½ tsp red pepper flakes', 'Aleppo pepper (pul biber)', 1, 'tsp', 'or ½ tsp red pepper flakes', false),
  ('44575bce-3db0-487e-b573-554c31f11535', 7, null, '¾ tsp kosher salt', 'kosher salt', 0.75, 'tsp', null, false),
  ('44575bce-3db0-487e-b573-554c31f11535', 8, null, '8 large eggs', 'large eggs', 8, null, null, false),
