insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('de3bec9b-4417-4e45-804c-369d91999706', 1, 'Herbs', '2 bunch flat-leaf parsley, thick stems removed', 'flat-leaf parsley', 2, 'bunch', 'thick stems removed', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 2, 'Herbs', '1 bunch fresh cilantro', 'fresh cilantro', 1, 'bunch', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 3, 'Herbs', '1 bunch fresh chives, or the green tops of 8 scallions', 'fresh chives', 1, 'bunch', 'or the green tops of 8 scallions', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 4, 'Herbs', '1 leek, green part only, thinly sliced', 'leek', 1, null, 'green part only, thinly sliced', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 5, 'Herbs', '2 tbsp dried fenugreek leaves (kasoori methi)', 'dried fenugreek leaves (kasoori methi)', 2, 'tbsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 6, 'Herbs', '4 tbsp vegetable oil', 'vegetable oil', 4, 'tbsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 7, 'Stew', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 8, 'Stew', '1 large onion, finely chopped', 'large onion', 1, null, 'finely chopped', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 9, 'Stew', '1 tsp ground turmeric', 'ground turmeric', 1, 'tsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 10, 'Stew', '2 lb boneless lamb shoulder, cut into 1-inch cubes', 'boneless lamb shoulder', 2, 'lb', 'cut into 1-inch cubes', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 11, 'Stew', '4 cups water', 'water', 4, 'cup', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 12, 'Stew', '1½ tsp kosher salt', 'kosher salt', 1.5, 'tsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 13, 'Stew', '½ tsp black pepper', 'black pepper', 0.5, 'tsp', null, false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 14, 'Stew', '4 dried limes (limoo amani), pierced with a knife; or the zest and juice of 1 lemon, added at the end', 'dried limes (limoo amani)', 4, null, 'pierced with a knife; or the zest and juice of 1 lemon, added at the end', false),
  ('de3bec9b-4417-4e45-804c-369d91999706', 15, 'Stew', '1 can kidney beans, 15 oz, drained and rinsed', 'kidney beans', 1, 'can', '15 oz, drained and rinsed', false);
