insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('de3bec9b-4417-4e45-804c-369d91999706', 1, 'Herbs', 'Pulse the parsley, cilantro, chives and leek in a food processor until finely chopped (or chop by hand). Fry them in 4 tbsp oil over medium-low heat, stirring often, until dark green, much reduced and fragrant, 20–25 minutes. Stir in the fenugreek for the last 2 minutes.', 1500, null, null),
  ('de3bec9b-4417-4e45-804c-369d91999706', 2, 'Stew', 'In a Dutch oven, cook the onion in 2 tbsp oil over medium heat until golden, about 10 minutes. Stir in the turmeric.', 600, null, null),
  ('de3bec9b-4417-4e45-804c-369d91999706', 3, 'Stew', 'Add the lamb and cook, turning, until browned on all sides, about 8 minutes.', 480, null, null),
  ('de3bec9b-4417-4e45-804c-369d91999706', 4, 'Stew', 'Add the water, salt and pepper and bring to a boil, skimming off any foam. Cover and simmer gently for 1 hour.', 3600, null, null),
  ('de3bec9b-4417-4e45-804c-369d91999706', 5, 'Stew', 'Stir in the fried herbs and the pierced dried limes. Cover and simmer until the lamb is very tender (well past the 145°F safe minimum) and a layer of oil rises to the top, about 1½ hours.', 5400, null, 62.8),
  ('de3bec9b-4417-4e45-804c-369d91999706', 6, 'Stew', 'Add the kidney beans and simmer uncovered for 20 minutes to thicken. Press the limes against the pot to release their juice, then taste for salt and sourness (add the lemon now if you used it instead).', 1200, null, null),
  ('de3bec9b-4417-4e45-804c-369d91999706', 7, null, 'Serve over steamed basmati rice, ideally with a crisp tahdig.', 120, null, null);

