values ('6cc846dd-a7e0-4edf-8be7-8735f0141866', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sabich', 'sabich-6cc846', 'Sabich', 'Warm pita stuffed with silky fried eggplant, sliced hard-cooked egg, chopped salad, tahini and tangy amba — Tel Aviv''s favourite street sandwich.', 'israeli', 2, 30, 30, 60, 4, 'main', null, 0, array['stove']::text[], array['vegetarian', 'lunch']::text[], array['Short on time? Brush the eggplant slices with oil and roast at 425°F for 20–25 minutes, turning once — lighter, but still good.', 'Amba is a tangy, fenugreek-scented mango pickle sold in jars at Middle Eastern and kosher shops.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['lunch', 'main', 'dinner']::text[], array['boil']::text[], array['tangy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'sabich', 'classic', 'Assemble just before eating. Fried eggplant and peeled eggs keep 3 days refrigerated.', null, 'owned', array['egg', 'gluten', 'sesame', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'dairy_free']::text[], array['globe eggplant', 'egg', 'tahini', 'lemon', 'garlic', 'persian cucumber', 'tomato', 'red onion', 'parsley', 'pita bread', 'hummu', 'dill pickle']::text[], 'dill pickle|egg|garlic|globe eggplant|hummu|lemon|parsley|persian cucumber|pita bread|red onion|tahini|tomato',
