insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 1, 'Eggplant', 'Sprinkle the eggplant slices with salt on both sides and set them on a rack for 20 minutes. Pat dry with paper towels.', 1200, null, null),
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 2, 'Eggs', 'Put the eggs in a saucepan, cover with cold water and bring to a boil. Turn off the heat, cover and leave 11 minutes until the yolks are firm, then cool in ice water, peel and slice.', 900, null, 71.1),
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 3, 'Eggplant', 'Heat ½ inch of oil in a heavy skillet to 350°F — the pan should be no more than half full. Fry the eggplant in batches until deep golden and creamy inside, 2–3 minutes per side. Drain on paper towels.', 900, 176.7, null),
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 4, 'Tahini sauce', 'Whisk the tahini, half the lemon juice and the garlic, then whisk in the cold water until smooth and pourable.', 180, null, null),
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 5, 'Salad', 'Toss the cucumbers, tomatoes, onion and parsley with the olive oil, the rest of the lemon juice and a pinch of salt.', 300, null, null),
  ('6cc846dd-a7e0-4edf-8be7-8735f0141866', 6, null, 'Open each pita and spread the inside with hummus. Layer in the eggplant, egg slices, salad and pickles, then spoon over tahini sauce and amba.', 300, null, null);

