values ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lamb-tagine-apricots', 'lamb-tagine-with-apricots-6cd1cf', 'Lamb Tagine with Apricots', 'Lamb shoulder braised with ginger, cinnamon and saffron until spoon-tender, finished with honeyed apricots, toasted almonds and sesame.', 'moroccan', 3, 25, 150, 175, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['entertaining', 'make-ahead']::text[], array['Made a day ahead, the flavours deepen. Reheat gently and add the almonds just before serving so they stay crunchy.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['entertaining', 'main', 'dinner', 'holiday']::text[], array['stew']::text[], array['fresh', 'aromatic']::text[], array['eid-al-adha']::text[], null, 'traditional', 'lamb-tagine-apricots', 'classic', 'Refrigerate up to 4 days or freeze (without the almonds) up to 3 months.', null, 'owned', array['sesame', 'tree_nut']::text[], array['lamb']::text[], array['gluten_free', 'dairy_free']::text[], array['lamb shoulder', 'onion', 'garlic', 'ground ginger', 'ground cinnamon', 'ground turmeric', 'saffron thread', 'cinnamon stick', 'cilantro', 'dried apricot', 'honey', 'blanched almond', 'sesame seed']::text[], 'blanched almond|cilantro|cinnamon stick|dried apricot|garlic|ground cinnamon|ground ginger|ground turmeric|honey|lamb shoulder|onion|saffron thread|sesame seed',
