insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 1, 'Tagine', 'Toss the lamb with the oil, garlic, ginger, cinnamon, turmeric, pepper, saffron and salt. Leave 30 minutes, or refrigerate overnight.', 1800, null, null),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 2, 'Tagine', 'Put the lamb and grated onions in a Dutch oven or tagine over medium heat and cook, stirring, until the onions soften and the meat colours, about 10 minutes.', 600, null, null),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 3, 'Tagine', 'Add the water and cinnamon stick, bring to a simmer, then cover and cook very gently until the lamb is spoon-tender (well past the 145°F safe minimum), 1½–2 hours. Add a splash of water if it gets dry.', 6300, null, 62.8),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 4, 'Apricots', 'Meanwhile, put the apricots in a small pan with the honey and a ladle of the cooking liquid. Simmer until plump and glossy, about 10 minutes.', 600, null, null),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 5, 'Garnish', 'Toast the almonds in a dry skillet over medium heat, shaking the pan, until golden, 4–5 minutes.', 300, null, null),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 6, 'Tagine', 'Uncover the tagine and simmer 15 minutes to reduce the sauce until it coats the meat. Stir in half the apricots.', 900, null, null),
  ('6cd1cffd-0344-4c26-a29e-dd465caf5cab', 7, null, 'Serve topped with the remaining apricots, the almonds, sesame seeds and cilantro, with bread or couscous.', 120, null, null);

