  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 16, 'Vegetables', '2 zucchini, halved crosswise and lengthwise', 'zucchini', 2, null, 'halved crosswise and lengthwise', false),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 17, 'Vegetables', '1 can chickpeas, 15 oz, drained and rinsed', 'chickpeas', 1, 'can', '15 oz, drained and rinsed', false),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 18, 'Couscous', '2 cups couscous', 'couscous', 2, 'cup', null, false),
