delete from public.recipe_instructions where recipe_id = 'c4856961-53c0-4dac-bb17-fd40dd26bf83';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 1, 'Broth', 'Heat the oil in a large Dutch oven over medium heat. Add the onion, tomatoes, ginger, turmeric, pepper and saffron and cook, stirring, until the onion softens, 8 minutes.', 480, null, null),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 2, 'Broth', 'Add 6 cups of the stock, the salt, the herb bundles, carrots, turnips and cabbage. Cover and simmer for 25 minutes.', 1500, null, null),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 3, 'Vegetables', 'Add the squash and chickpeas and simmer 10 minutes, then add the zucchini and simmer until everything is tender but holding its shape, 10–12 minutes more.', 1320, null, null),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 4, 'Couscous', 'Bring the remaining 2 cups of stock to a boil with the olive oil. Pour it over the couscous in a wide bowl, cover and leave 5 minutes, then fluff with a fork, rubbing out any lumps.', 300, null, null),
  ('c4856961-53c0-4dac-bb17-fd40dd26bf83', 5, null, 'Discard the herb bundles and taste the broth for salt. Mound the couscous on a platter, make a well in the middle and pile the vegetables in a cone on top. Ladle some broth over and serve the rest alongside, with harissa.', 300, null, null);

