values ('2348c04c-c577-4a5e-a215-6122360aba8d', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'koshari', 'koshari-2348c0', 'Koshari', 'Cairo''s favourite street meal: lentils and rice, macaroni and chickpeas under a spicy tomato sauce, sharp garlic vinegar and a pile of crispy fried onions.', 'egyptian', 2, 20, 60, 80, 6, 'main', null, 0, array['stove']::text[], array['vegan', 'budget']::text[], array['Cooking the rice and sauce in the onion-frying oil is what gives koshari its flavour, so don''t throw it out.', 'Short on time? Store-bought crispy fried onions work well.']::text[], 'https://images.unsplash.com/photo-1779592639268-acee1edc1133', 'Koshari of rice, lentils, macaroni and chickpeas topped with fried onions', 'Alexandra Tran', 'https://unsplash.com/@alexgoesglobal', 'https://unsplash.com/photos/spoonful-of-koshary-with-pasta-chickpeas-and-fried-onions-jj563epOwdw', 'unsplash', true, 'public', false,
  'pending_review', array['budget', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['spicy', 'tangy', 'aromatic']::text[], '{}'::text[], 'Cairo', 'traditional', 'koshari', 'classic', 'Refrigerate the components separately up to 4 days. Keep the onions airtight at room temperature so they stay crisp.', null, 'owned', array['gluten', 'wheat']::text[], array['beans']::text[], array['pescatarian', 'vegetarian', 'vegan', 'dairy_free']::text[], array['onion', 'brown lentil', 'medium-grain rice', 'ground cumin', 'elbow macaroni', 'chickpea', 'garlic', 'tomato sauce', 'ground coriander', 'pepper flake', 'white vinegar']::text[], 'brown lentil|chickpea|elbow macaroni|garlic|ground coriander|ground cumin|medium-grain rice|onion|pepper flake|tomato sauce|white vinegar',
  null, null, null, null, null, null, null, null)
