values ('e9611ab4-bcb5-45bb-a6c0-28ca0bf4a1ac', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'shiro-wat', 'shiro-wat-e9611a', 'Shiro Wat', 'A silky, berbere-spiced stew of ground chickpeas, made with oil as it is on Ethiopian fasting days — cheap, quick and deeply savoury.', 'ethiopian', 2, 10, 35, 45, 4, 'main', null, 0, array['stove']::text[], array['vegan', 'budget']::text[], array['Shiro powder is ground chickpeas (sometimes with broad beans) already blended with spices; look for it at Ethiopian and East African grocers or online.', 'It thickens fast as it cools — loosen it with hot water to a creamy, pourable texture.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['budget', 'main', 'dinner']::text[], array['stew', 'raw']::text[], array['spicy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'shiro-wat', 'classic', 'Refrigerate up to 4 days; reheat with a splash of water.', null, 'owned', '{}'::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['red onion', 'garlic', 'ginger', 'berbere spice', 'tomato paste', 'tomato', 'shiro powder']::text[], 'berbere spice|garlic|ginger|red onion|shiro powder|tomato|tomato paste',
  null, null, null, null, null, null, null, null)
