delete from public.recipe_instructions where recipe_id = 'fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 1, 'Spiced butter', 'Melt the butter with the garlic, ginger, fenugreek, cardamom and turmeric over low heat. Simmer very gently until the milk solids sink and it smells nutty, about 15 minutes, then strain.', 900, null, null),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 2, 'Stew', 'Rub the chicken with the lemon juice and 1 tsp salt and refrigerate while you cook the onions.', 300, null, null),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 3, 'Stew', 'Chop the onions very finely in a food processor. Cook them in a dry Dutch oven over medium-low heat, stirring often, until much reduced, soft and jammy, 30–40 minutes. Add a spoonful of water if they start to catch.', 2100, null, null),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 4, 'Stew', 'Stir in ¼ cup of the spiced butter, the berbere and the tomato paste and cook, stirring, until deep red and the butter separates, about 10 minutes. Add the garlic and ginger for 2 minutes.', 720, null, null),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 5, 'Stew', 'Add the chicken, water and remaining salt. Cover and simmer gently, turning the pieces now and then, until the chicken is very tender and 165°F at the bone, 40–45 minutes.', 2520, null, 73.9),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 6, 'Stew', 'Meanwhile, cover the eggs with cold water, bring to a boil, then cover off the heat for 11 minutes until the yolks are firm. Cool, peel and score each egg with a few shallow cuts.', 900, null, 71.1),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 7, 'Stew', 'Add the eggs and the rest of the spiced butter and simmer uncovered for 10 minutes, spooning sauce over the eggs, until the sauce coats a spoon.', 600, null, null),
  ('fc40fdfa-1a1f-42d2-8c3e-a67c60f7d48b', 8, null, 'Serve with injera or rice, giving everyone an egg.', 120, null, null);

