insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 1, 'Yaji spice', 'Pulse the peanuts in a food processor or spice grinder to a fine powder, stopping before it turns to paste. Mix with the paprika, cayenne, ginger, garlic and onion powders, bouillon and salt.', 300, null, null),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 2, 'Beef', 'Soak 8–10 bamboo skewers in water for 30 minutes. Thread the beef onto them in flat, ribbon-like folds.', 1800, null, null),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 3, 'Beef', 'Brush the beef with the oil and coat it generously with two-thirds of the yaji, pressing it on. Rest 15 minutes, or refrigerate up to overnight.', 900, null, null),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 4, 'Beef', 'Heat the grill to high, about 500°F, and oil the grates. Grill the skewers until charred at the edges and 145°F inside, 3–4 minutes per side. Rest 3 minutes.', 480, 260, 62.8),
  ('0cae602a-42a7-41bb-ac3f-8b066b2935ea', 5, null, 'Sprinkle with the remaining yaji and serve with the onion, tomato and cucumber.', 120, null, null);

