values ('e12231ae-94e3-4d85-8cfc-db3756a867d4', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kelewele', 'kelewele-e12231', 'Kelewele', 'Very ripe plantain cubes tossed in ginger, chili and warm spices, then fried until caramelised and crisp-edged — Ghana''s favourite street snack.', 'ghanaian', 2, 25, 15, 40, 4, 'side', null, 0, array['stove']::text[], array['vegan', 'budget']::text[], array['The riper the plantain, the sweeter and darker the kelewele — the skins should be mostly black.', 'Keep the oil below 360°F: the sugar in ripe plantains burns quickly.']::text[], 'https://images.pexels.com/photos/35136066/pexels-photo-35136066.jpeg', 'Fried plantain pieces with peanuts in a white bowl on a woven placemat', 'Ophelia Acquah', 'https://www.pexels.com/@ghanawithophelia/', 'https://www.pexels.com/photo/fried-plantains-with-peanuts-in-a-bowl-35136066/', 'pexels', true, 'public', false,
  'pending_review', array['side', 'budget']::text[], array['roast']::text[], array['spicy', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'kelewele', 'classic', 'Best hot. Refrigerate leftovers up to 2 days and re-crisp in a 400°F oven or air fryer for 5 minutes.', null, 'owned', array['peanut']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'vegan', 'gluten_free', 'dairy_free']::text[], array['very plantain', 'ginger', 'onion', 'garlic', 'cayenne', 'ground clove', 'ground nutmeg']::text[], 'cayenne|garlic|ginger|ground clove|ground nutmeg|onion|very plantain',
  null, null, null, null, null, null, null, null)
