values ('4022a9e3-9b4a-4832-8bc2-c9c8bfd5c689', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'chicken-yassa', 'chicken-yassa-4022a9', 'Chicken Yassa', 'Chicken marinated in lemon, mustard and a mountain of onions, browned, then braised in those soft, tangy onions — adapted by browning in a pan rather than over charcoal.', 'senegalese', 2, 25, 65, 90, 4, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['make-ahead', 'comfort']::text[], array['For the smoky traditional flavour, grill the marinated chicken over medium-high heat instead of browning it in the pan.', 'Wash your hands, board and anything else that touched the raw chicken marinade before handling other food.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'comfort']::text[], array['stew']::text[], array['spicy']::text[], '{}'::text[], null, 'adapted', 'chicken-yassa', 'classic', 'Refrigerate up to 4 days; the flavours improve overnight.', null, 'owned', '{}'::text[], array['chicken']::text[], array['dairy_free']::text[], array['onion', 'lemon', 'dijon mustard', 'garlic', 'bay leave', 'chicken stock']::text[], 'bay leave|chicken stock|dijon mustard|garlic|lemon|onion',
  null, null, null, null, null, null, null, null)
