values ('89bd4146-7e11-489f-a881-2b0ec1a0353e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'groundnut-soup', 'groundnut-soup-89bd41', 'Groundnut Soup', 'Ghanaian peanut soup: chicken simmered in a rich, gently spicy tomato and peanut broth until a red sheen of oil rises to the top.', 'ghanaian', 3, 20, 75, 95, 6, 'main', null, 0, array['stove', 'blender']::text[], array['comfort', 'freezer-friendly']::text[], array['Use natural peanut butter (just peanuts, maybe salt): it behaves like Ghanaian groundnut paste, while sweetened brands make the soup taste off.', 'Leave the scotch bonnet out of the blender and float it whole in the pot for gentle heat.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew']::text[], array['spicy']::text[], '{}'::text[], null, 'traditional', 'groundnut-soup', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months; stir well when reheating.', null, 'owned', array['peanut']::text[], array['chicken']::text[], array['gluten_free', 'dairy_free']::text[], array['drumstick thigh', 'onion', 'ginger', 'garlic', 'tomato', 'bonnet pepper', 'tomato paste', 'peanut butter']::text[], 'bonnet pepper|drumstick thigh|garlic|ginger|onion|peanut butter|tomato|tomato paste',
  null, null, null, null, null, null, null, null)
