insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 1, null, 'Put the chicken, sliced onion, half the ginger and garlic, the salt and ½ cup of the water in a large pot. Cover and cook over medium heat, stirring now and then, until the chicken releases its juices, 15 minutes.', 900, null, null),
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 2, null, 'Blend the tomatoes, chopped onion, remaining ginger and garlic and the scotch bonnet with 1 cup of the water until smooth. Hold the blender lid down with a towel.', 180, null, null),
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 3, null, 'Add the purée, tomato paste and 3 cups of the water to the pot and simmer 15 minutes.', 900, null, null),
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 4, null, 'Whisk the peanut butter with 1½ cups of hot liquid from the pot until smooth, then stir it back into the soup.', 180, null, null),
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 5, null, 'Simmer partly covered, stirring regularly so the bottom doesn''t catch, until reddish oil rises to the surface and the chicken is tender and 165°F at the bone, 35–40 minutes.', 2280, null, 73.9),
  ('89bd4146-7e11-489f-a881-2b0ec1a0353e', 6, null, 'Thin with the remaining water if needed — it should be pourable, not thick like stew. Taste for salt and serve with rice balls (omo tuo), fufu or rice.', 120, null, null);

