delete from public.recipe_instructions where recipe_id = '74033305-f563-4b9e-9c7c-b7ff2b81f201';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 1, 'Chicken', 'Season the chicken with 1 tsp salt. Brown it skin side down in the oil in a Dutch oven over medium-high heat, 6–8 minutes, then set aside. Pour off all but about 2 tbsp of the fat.', 480, null, null),
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 2, 'Chicken', 'Cook the onions over medium heat until soft and golden, 10 minutes. Add the pepper, tomato and remaining salt and cook 3 minutes.', 780, null, null),
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 3, 'Chicken', 'Take the pot off the heat and stir in the paprika (it scorches easily), then the stock. Return the chicken skin side up, cover and simmer gently until tender and 165°F at the bone, 35–40 minutes.', 2280, null, 73.9),
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 4, 'Nokedli', 'Meanwhile, bring a large pot of salted water to a boil. Mix the flour, eggs, water and salt into a thick, sticky batter. Press it through a spaetzle maker or the holes of a colander into the water and cook until the dumplings float, 2–3 minutes. Drain and toss with the butter.', 600, null, null),
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 5, 'Chicken', 'Lift out the chicken. Whisk the flour into the sour cream, then whisk in a ladle of the hot sauce to temper it, and stir it all back into the pot off the boil.', 180, null, null),
  ('74033305-f563-4b9e-9c7c-b7ff2b81f201', 6, 'Chicken', 'Return the chicken and warm through over low heat for 5 minutes without letting it boil. Serve over the nokedli.', 300, null, null);

