values ('b292a61d-ba93-4d7a-b140-d44d161ebea3', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'irish-stew', 'irish-stew-b292a6', 'Irish Stew', 'Lamb, onions and two kinds of potato layered and slowly baked with thyme, so the floury potatoes melt to thicken the broth while the waxy ones hold their shape.', 'irish', 2, 25, 135, 160, 6, 'main', null, 0, array['stove', 'oven', 'dutch_oven']::text[], array['comfort', 'make-ahead']::text[], array['Purists argue over carrots — leave them out for the plainest, oldest version.', 'Bone-in lamb neck makes an even richer broth; cook 30 minutes longer and pull out the bones before serving.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner', 'soup']::text[], array['stew', 'bake']::text[], array['fresh']::text[], '{}'::text[], null, 'traditional', 'irish-stew', 'classic', 'Refrigerate up to 4 days or freeze up to 3 months.', null, 'owned', '{}'::text[], array['lamb']::text[], array['dairy_free']::text[], array['lamb shoulder', 'russet potato', 'gold potato', 'onion', 'carrot', 'thyme', 'bay leave', 'lamb stock', 'parsley']::text[], 'bay leave|carrot|gold potato|lamb shoulder|lamb stock|onion|parsley|russet potato|thyme',
