insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b292a61d-ba93-4d7a-b140-d44d161ebea3', 1, null, 'Heat the oven to 325°F. Season the lamb with the salt and pepper.', 300, 162.8, null),
  ('b292a61d-ba93-4d7a-b140-d44d161ebea3', 2, null, 'Layer the sliced russets over the bottom of a Dutch oven, then the lamb, onions, carrots, thyme and bay, seasoning each layer lightly. Finish with the halved Yukon Golds on top.', 600, null, null),
  ('b292a61d-ba93-4d7a-b140-d44d161ebea3', 3, null, 'Pour in the stock until it almost covers everything and bring to a simmer on the stovetop.', 600, null, null),
  ('b292a61d-ba93-4d7a-b140-d44d161ebea3', 4, null, 'Cover tightly and bake until the lamb is very tender (well past the 145°F safe minimum), about 2 hours.', 7200, 162.8, 62.8),
  ('b292a61d-ba93-4d7a-b140-d44d161ebea3', 5, null, 'Skim off excess fat and remove the thyme stems and bay leaves. Stir gently so the broken-down russets thicken the broth, then scatter with parsley.', 300, null, null);

