values ('db14e26a-3273-4344-855f-4b3d4a2fa56f', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tomato-and-egg-stir-fry', 'tomato-and-egg-stir-fry-db14e2', 'Tomato and Egg Stir-Fry', 'Fluffy scrambled eggs folded into sweet-sour, juicy tomatoes — the dish nearly every Chinese home cook learns first, on the table in 15 minutes.', 'chinese', 2, 10, 8, 18, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'budget', 'kid-friendly']::text[], array['Out-of-season tomatoes? Add 1 tablespoon of ketchup with the sugar for depth and color.']::text[], 'https://images.unsplash.com/photo-1629180052394-bedb0e4445fd', 'Stir-fried tomatoes and soft scrambled egg on a white plate', 'Helen Van', 'https://unsplash.com/@uynnha', 'https://unsplash.com/photos/cooked-food-on-white-ceramic-plate-6QE9lltiDvc', 'unsplash', true, 'public', false,
  'pending_review', array['quick', 'budget', 'main', 'dinner', 'comfort']::text[], array['stir_fry']::text[], '{}'::text[], '{}'::text[], null, 'traditional', 'tomato-egg-stir-fry', 'classic', 'Best eaten right away. Refrigerate up to 2 days and reheat gently in the microwave.', null, 'owned', array['egg', 'gluten', 'wheat']::text[], '{}'::text[], array['pescatarian', 'vegetarian', 'gluten_free', 'dairy_free']::text[], array['egg', 'tomato', 'garlic', 'scallion', 'cornstarch', 'jasmine rice']::text[], 'cornstarch|egg|garlic|jasmine rice|scallion|tomato',
  null, null, null, null, null, null, null, null)
