insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('db14e26a-3273-4344-855f-4b3d4a2fa56f', 1, null, 'Beat the eggs with half the salt and the Shaoxing wine until no streaks of white remain.', 60, null, null),
  ('db14e26a-3273-4344-855f-4b3d4a2fa56f', 2, null, 'Heat 2 tablespoons of the oil in a wok or large nonstick skillet over medium-high heat. Pour in the eggs, let them puff for a few seconds, then push them gently into large soft curds. Cook until set with no liquid egg left (160°F), about 1 minute, and tip onto a plate.', 120, null, 71.1),
  ('db14e26a-3273-4344-855f-4b3d4a2fa56f', 3, null, 'Add the remaining oil, the garlic and scallion whites and stir-fry 20 seconds. Add the tomatoes, sugar and remaining salt and cook, pressing a few wedges with the spatula, until they slump and release their juice, 3–4 minutes.', 240, null, null),
  ('db14e26a-3273-4344-855f-4b3d4a2fa56f', 4, null, 'Stir in the cornstarch mixture and bubble until the sauce turns glossy, about 30 seconds.', null, null, null),
  ('db14e26a-3273-4344-855f-4b3d4a2fa56f', 5, null, 'Return the eggs, fold once or twice so they stay in big pieces, scatter with scallion greens and serve over rice.', 60, null, null);

