values ('33d095e0-269b-4e8d-a03f-d55fed250ad8', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'kung-pao-chicken', 'kung-pao-chicken-33d095', 'Kung Pao Chicken', 'Velveted chicken stir-fried hard with toasted dried chiles, Sichuan peppercorns and peanuts in a glossy, tingly sweet-sour sauce.', 'sichuan', 3, 25, 10, 35, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['The dried chiles are for aroma, not for eating — most people push them aside.', 'Sichuan peppercorns cause a numbing tingle; halve them the first time if you''re unsure.']::text[], 'https://images.unsplash.com/photo-1605704922285-e82455dba38b', 'Bowl of kung pao chicken stir-fry', 'Karolina Kołodziejczak', 'https://unsplash.com/@rabbit_in_blue', 'https://unsplash.com/photos/cooked-food-on-white-ceramic-bowl-8qFMa9-ljD8', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stir_fry', 'pan_fry']::text[], array['tangy', 'savory']::text[], '{}'::text[], 'Sichuan', 'traditional', 'kung-pao-chicken', 'classic', 'Refrigerate up to 3 days. The peanuts soften, so reheat in a hot skillet rather than the microwave.', null, 'owned', array['gluten', 'peanut', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['soy sauce', 'shaoxing wine', 'cornstarch', 'black vinegar', 'red chile', 'sichuan peppercorn', 'garlic', 'ginger', 'scallion', 'roasted peanut']::text[], 'black vinegar|cornstarch|garlic|ginger|red chile|roasted peanut|scallion|shaoxing wine|sichuan peppercorn|soy sauce',
  null, null, null, null, null, null, null, null)
