values ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'dan-dan-noodles', 'dan-dan-noodles-cf086e', 'Dan Dan Noodles', 'Springy wheat noodles over a pool of sesame, chili oil and black vinegar sauce, topped with crisp, savory pork — a Chengdu street snack made at home.', 'sichuan', 2, 15, 15, 30, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['Ya cai (preserved mustard greens) comes in small packets at Asian grocers and keeps for months; it adds the classic salty-funky note.']::text[], 'https://images.unsplash.com/photo-1791411064433-7050bfb22db9', 'Bowl of dan dan noodles with chili oil, sesame and green onions', 'Zoshua Colah', 'https://unsplash.com/@zoshuacolah', 'https://unsplash.com/photos/dan-dan-noodles-with-chili-oil-V6nsoFR5jbE', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'quick']::text[], array['boil']::text[], array['spicy', 'tangy', 'fresh', 'savory']::text[], '{}'::text[], 'Sichuan', 'traditional', 'dan-dan-noodles', 'classic', 'Keep the sauce and pork separately in the fridge up to 4 days; cook noodles fresh.', null, 'owned', array['gluten', 'peanut', 'sesame', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['ground pork', 'shaoxing wine', 'soy sauce', 'sesame paste', 'black vinegar', 'chili oil', 'sichuan peppercorn', 'garlic', 'wheat noodle', 'bok choy', 'scallion']::text[], 'black vinegar|bok choy|chili oil|garlic|ground pork|scallion|sesame paste|shaoxing wine|sichuan peppercorn|soy sauce|wheat noodle',
  null, null, null, null, null, null, null, null)
