insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', 1, 'Pork', 'Heat the oil in a skillet over medium-high heat. Add the pork and fry, breaking it into small crumbs, until browned, crisp at the edges, no pink remains and it reaches 160°F, about 6 minutes.', 360, null, 71.1),
  ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', 2, 'Pork', 'Add the Shaoxing wine, soy sauce and mustard greens and fry 1 more minute until dry and toasty. Keep warm.', 60, null, null),
  ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', 3, 'Sauce', 'Whisk the sesame paste with the soy sauce until smooth, then whisk in the vinegar, sugar, chili oil, ground Sichuan pepper and garlic. Loosen with 2–3 tablespoons hot water from the noodle pot. Divide among four bowls.', null, null, null),
  ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', 4, 'Noodles', 'Boil the noodles in plenty of water until just tender, following the package (usually 3–5 minutes); add the bok choy for the last minute.', 240, null, null),
  ('cf086e9a-ad0e-4bfb-bda1-74189b4ee464', 5, null, 'Drain, then pile the noodles and bok choy into the bowls. Top with the pork, scallions and peanuts and toss everything together at the table.', 60, null, null);

