values ('2deaf634-0aa5-4de5-aee0-4171dc1ecf8e', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sichuan-dry-fried-green-beans', 'dry-fried-green-beans-2deaf6', 'Dry-Fried Green Beans', 'Green beans blistered until wrinkled and sweet, then tossed with crisp pork, preserved greens and chiles; we blister them in a skillet instead of deep-frying.', 'sichuan', 2, 10, 15, 25, 4, 'side', null, 0, array['stove', 'cast_iron']::text[], array['weeknight']::text[], array['Dry the beans thoroughly after washing — wet beans steam instead of blistering and the oil spits.']::text[], 'https://images.unsplash.com/photo-1573409157829-fc549dc70bc3', 'Stir-fried green beans with minced meat on a plate', 'Jacques Bopp', 'https://unsplash.com/@jacquesbopp', 'https://unsplash.com/photos/plate-of-food-UYThDZZVs4U', 'unsplash', true, 'public', false,
  'pending_review', array['side']::text[], '{}'::text[], array['fresh', 'savory']::text[], '{}'::text[], 'Sichuan', 'adapted', 'dry-fried-green-beans', 'classic', 'Best fresh. Refrigerate up to 2 days and reheat in a hot, dry skillet.', null, 'owned', array['gluten', 'soy', 'wheat']::text[], array['pork', 'beans']::text[], array['dairy_free']::text[], array['green bean', 'ground pork', 'red chile', 'sichuan peppercorn', 'garlic', 'ginger', 'mustard green', 'shaoxing wine', 'soy sauce']::text[], 'garlic|ginger|green bean|ground pork|mustard green|red chile|shaoxing wine|sichuan peppercorn|soy sauce',
  null, null, null, null, null, null, null, null)
