  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 10, 'Filling', '1 tsp cornstarch', 'cornstarch', 1, 'tsp', null, false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 11, 'Filling', '36 round wheat dumpling wrappers, gyoza skins, thawed if frozen', 'round wheat dumpling wrappers', 36, null, 'gyoza skins, thawed if frozen', false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 12, 'Cooking', '2 tbsp vegetable oil, divided', 'vegetable oil', 2, 'tbsp', 'divided', false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 13, 'Cooking', '⅔ cup water, divided', 'water', 0.66, 'cup', 'divided', false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 14, 'Dipping sauce', '3 tbsp soy sauce', 'soy sauce', 3, 'tbsp', null, false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 15, 'Dipping sauce', '3 tbsp rice vinegar', 'rice vinegar', 3, 'tbsp', null, false),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 16, 'Dipping sauce', '1 tsp chili oil', 'chili oil', 1, 'tsp', null, true);
delete from public.recipe_instructions where recipe_id = 'fefb07f7-5c9d-4e20-9048-680e756312f1';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 1, 'Filling', 'Toss the cabbage with the salt and let it stand 10 minutes. Squeeze it hard in a clean towel to remove as much water as you can.', 600, null, null),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 2, 'Filling', 'Mix the cabbage with the pork, scallions, garlic, ginger, soy sauce, sake, sesame oil and cornstarch, stirring in one direction until sticky.', null, null, null),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 3, 'Filling', 'Put a heaping teaspoon of filling in the middle of a wrapper, wet half the edge with water, fold in half and pinch 4–5 pleats along the front edge to seal. Set on a floured tray and repeat.', 1800, null, null),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 4, 'Cooking', 'Heat 1 tablespoon oil in a large nonstick skillet with a lid over medium-high heat. Arrange half the gyoza flat-side down in tight rows and fry until the bottoms are golden, about 2 minutes.', 120, null, null),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 5, 'Cooking', 'Pour in ⅓ cup water (it will spatter), cover at once and steam until the wrappers turn translucent and the filling reaches 160°F, about 5 minutes.', 300, null, 71.1),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 6, 'Cooking', 'Uncover and cook until the water is gone and the bottoms are crisp again, 1–2 minutes. Slide onto a plate crisp-side up and repeat with the rest.', 120, null, null),
  ('fefb07f7-5c9d-4e20-9048-680e756312f1', 7, 'Dipping sauce', 'Stir the soy sauce, vinegar and chili oil together and serve alongside.', null, null, null);

