values ('9a61a023-5cd9-41b3-ab68-759fe02a9ff2', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'oyakodon', 'oyakodon-9a61a0', 'Oyakodon', 'Chicken and onion simmered in sweet-savory dashi, then bound with softly set egg and slid over rice — a one-pan Japanese comfort bowl.', 'japanese', 1, 10, 15, 25, 4, 'main', null, 0, array['stove']::text[], array['weeknight', 'comfort', 'kid-friendly']::text[], array['Instant dashi granules dissolved in hot water are a quick, authentic stand-in for homemade dashi.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['quick', 'comfort', 'main', 'dinner']::text[], array['stew']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'oyakodon', 'classic', 'Best eaten right away; the egg toughens when reheated.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'soy', 'wheat']::text[], array['chicken']::text[], array['dairy_free']::text[], array['yellow onion', 'dashi', 'soy sauce', 'mirin', 'egg', 'scallion', 'short-grain rice']::text[], 'dashi|egg|mirin|scallion|short-grain rice|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
