insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e0edae6-b6b1-4896-8f41-c1d6c207e68b', 1, 'Katsu sauce', 'Stir the ketchup, Worcestershire, soy sauce and sugar together until smooth.', null, null, null),
  ('7e0edae6-b6b1-4896-8f41-c1d6c207e68b', 2, 'Pork', 'Snip the fat along the edge of each chop in 3–4 places so they stay flat. Season with salt and pepper, then coat in flour, dip in egg and press firmly into the panko.', 600, null, null),
  ('7e0edae6-b6b1-4896-8f41-c1d6c207e68b', 3, 'Pork', 'Pour the oil into a heavy pot no more than half full and heat to 340–350°F. Keep children and pets away and never leave hot oil unattended.', 480, 176.7, null),
  ('7e0edae6-b6b1-4896-8f41-c1d6c207e68b', 4, 'Pork', 'Deep-fry two cutlets at a time, turning once, until deep golden and 145°F in the center, 5–6 minutes. Drain on a rack and rest 3 minutes; let the oil come back to temperature between batches.', 720, 176.7, 62.8),
  ('7e0edae6-b6b1-4896-8f41-c1d6c207e68b', 5, null, 'Drain the cabbage well. Slice the cutlets into strips and serve with the cabbage, rice, lemon and katsu sauce.', 120, null, null);

