values ('8a072cd4-1989-473f-9a25-403edc5b992c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'okonomiyaki-osaka', 'okonomiyaki-8a072c', 'Okonomiyaki', 'Osaka''s savory cabbage pancake, griddled with crisp pork belly and finished with sweet-tangy sauce, mayo and smoky bonito flakes.', 'japanese', 2, 20, 25, 45, 4, 'main', null, 0, array['stove']::text[], array['comfort', 'budget']::text[], array['Bacon works in place of pork belly — use thin-cut and expect it to be saltier.']::text[], 'https://images.unsplash.com/photo-1764520406362-b1673b2213bf', 'Okonomiyaki cooking on a teppanyaki griddle', 'Yosuke Ota', 'https://unsplash.com/@yosuke_ota', 'https://unsplash.com/photos/okonomiyaki-cooking-on-a-hot-plate-IveJAkyk7q8', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'budget', 'comfort']::text[], '{}'::text[], array['savory']::text[], '{}'::text[], 'Osaka', 'traditional', 'okonomiyaki', 'classic', 'Refrigerate (without toppings) up to 2 days; reheat in a covered skillet over medium-low.', null, 'owned', array['egg', 'fish', 'gluten', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['dashi', 'baking powder', 'egg', 'green cabbage', 'scallion', 'pork belly', 'ketchup', 'worcestershire sauce', 'soy sauce', 'honey', 'japanese mayonnaise']::text[], 'baking powder|dashi|egg|green cabbage|honey|japanese mayonnaise|ketchup|pork belly|scallion|soy sauce|worcestershire sauce',
