insert into public.recipe_ingredients (recipe_id, position, component, raw_text, item, original_quantity, original_unit, preparation, is_optional) values
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 1, 'Batter', '1 cup all-purpose flour', 'all-purpose flour', 1, 'cup', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 2, 'Batter', '¾ cup dashi, or water', 'dashi', 0.75, 'cup', 'or water', false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 3, 'Batter', '½ tsp baking powder', 'baking powder', 0.5, 'tsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 4, 'Batter', '½ tsp kosher salt', 'kosher salt', 0.5, 'tsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 5, 'Batter', '4 large eggs', 'large eggs', 4, null, null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 6, 'Batter', '5 cups green cabbage, finely shredded (about ½ small head)', 'green cabbage', 5, 'cup', 'finely shredded (about ½ small head)', false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 7, 'Batter', '4 scallions, thinly sliced', 'scallions', 4, null, 'thinly sliced', false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 8, 'Batter', '¼ cup tenkasu (tempura bits), or crushed rice crackers', 'tenkasu (tempura bits)', 0.25, 'cup', 'or crushed rice crackers', true),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 9, 'Cooking', '2 tbsp vegetable oil', 'vegetable oil', 2, 'tbsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 10, 'Cooking', '8 oz thinly sliced pork belly, cut into 4-inch strips', 'thinly sliced pork belly', 8, 'oz', 'cut into 4-inch strips', false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 11, 'Topping', '3 tbsp ketchup', 'ketchup', 3, 'tbsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 12, 'Topping', '2 tbsp Worcestershire sauce', 'Worcestershire sauce', 2, 'tbsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 13, 'Topping', '1 tbsp soy sauce', 'soy sauce', 1, 'tbsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 14, 'Topping', '1 tbsp honey', 'honey', 1, 'tbsp', null, false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 15, 'Topping', '¼ cup Japanese mayonnaise, or regular mayonnaise', 'Japanese mayonnaise', 0.25, 'cup', 'or regular mayonnaise', false),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 16, 'Topping', '1 cup bonito flakes (katsuobushi)', 'bonito flakes (katsuobushi)', 1, 'cup', null, true),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 17, 'Topping', '1 tbsp aonori (powdered seaweed)', 'aonori (powdered seaweed)', 1, 'tbsp', null, true);
delete from public.recipe_instructions where recipe_id = '8a072cd4-1989-473f-9a25-403edc5b992c';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 1, 'Topping', 'Stir the ketchup, Worcestershire, soy sauce and honey together for the okonomiyaki sauce.', null, null, null),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 2, 'Batter', 'Whisk the flour, dashi, baking powder and salt into a smooth batter, then whisk in the eggs. Fold in the cabbage, scallions and tenkasu until every shred is coated — don''t overmix.', 180, null, null),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 3, 'Cooking', 'Heat half the oil in a large nonstick skillet over medium heat. Spoon in half the batter and shape into a round about 1 inch thick. Lay half the pork belly strips over the top.', 60, null, null),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 4, 'Cooking', 'Cook until the bottom is deep golden, about 5 minutes. Flip with two spatulas (pork-side down), press lightly, cover and cook until the pork is crisp and the center is set (160°F), 5–6 minutes.', 660, null, 71.1),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 5, 'Cooking', 'Flip once more and cook 1 minute. Slide onto a plate pork-side up and repeat with the rest.', 60, null, null),
  ('8a072cd4-1989-473f-9a25-403edc5b992c', 6, 'Topping', 'Brush with the sauce, zigzag the mayonnaise over, and finish with bonito flakes and aonori. Cut into wedges to share.', null, null, null);

