values ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'miso-soup-tofu-wakame', 'miso-soup-18efb4', 'Miso Soup', 'A clean kombu and bonito dashi whisked with miso and filled with silky tofu, wakame and scallions — ten minutes from scratch.', 'japanese', 1, 5, 20, 25, 4, 'main', null, 0, array['stove']::text[], array['quick', 'budget']::text[], array['For a shortcut, dissolve 1½ teaspoons instant dashi granules in 4 cups hot water and skip the first three steps.']::text[], 'https://images.unsplash.com/photo-1763470260582-894ae15f43bb', 'Wooden bowl of miso soup with tofu, seaweed and scallions', 'note thanun', 'https://unsplash.com/@notethanun', 'https://unsplash.com/photos/bowl-of-miso-soup-with-tofu-and-seaweed-HQNhc58_6mI', 'unsplash', true, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'quick', 'budget']::text[], array['steam', 'boil']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'miso-soup', 'classic', 'Dashi keeps 4 days refrigerated. Miso soup is best fresh; reheat leftovers gently without boiling.', null, 'owned', array['fish', 'soy']::text[], array['tofu']::text[], array['pescatarian', 'gluten_free', 'dairy_free']::text[], array['kombu', 'bonito flake', 'wakame seaweed', 'yellow miso', 'silken tofu', 'scallion']::text[], 'bonito flake|kombu|scallion|silken tofu|wakame seaweed|yellow miso',
  null, null, null, null, null, null, null, null)
