insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 1, 'Dashi', 'Soak the kombu in the cold water in a saucepan for at least 10 minutes.', 600, null, null),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 2, 'Dashi', 'Heat over medium until small bubbles form around the edge, then lift out the kombu before it boils, about 8 minutes.', 480, null, null),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 3, 'Dashi', 'Bring to a boil, add the bonito flakes, turn off the heat and steep 3 minutes. Strain through a fine sieve without pressing, and return the dashi to the pan.', 180, null, null),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 4, 'Soup', 'Soak the wakame in warm water for 5 minutes until it unfurls, then drain.', 300, null, null),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 5, 'Soup', 'Warm the dashi over low heat. Put the miso in a ladle or sieve, dip it into the pot and whisk until dissolved.', 60, null, null),
  ('18efb42f-bf8c-4ca3-9a33-f11bc3c6bf5c', 6, 'Soup', 'Add the tofu and wakame and heat until steaming but not boiling, 2 minutes — boiling dulls the miso. Serve topped with scallions.', 120, null, null);

