  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stir_fry', 'boil']::text[], array['spicy', 'tangy', 'savory']::text[], '{}'::text[], null, 'traditional', 'bibimbap', 'classic', 'Keep vegetables, beef and rice separately, refrigerated, up to 3 days. Fry eggs fresh.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'gluten', 'sesame', 'soy', 'wheat']::text[], array['beef', 'beans']::text[], array['dairy_free']::text[], array['sirloin ribeye', 'soy sauce', 'garlic', 'sesame oil', 'spinach', 'bean sprout', 'carrot', 'zucchini', 'shiitake mushroom', 'gochujang', 'rice vinegar', 'short-grain rice', 'egg', 'sesame seed']::text[], 'bean sprout|carrot|egg|garlic|gochujang|rice vinegar|sesame oil|sesame seed|shiitake mushroom|short-grain rice|sirloin ribeye|soy sauce|spinach|zucchini',
  null, null, null, null, null, null, null, null)
