insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 1, 'Beef', 'Toss the beef with the soy sauce, sugar, garlic and sesame oil and let it marinate while you prepare the vegetables.', 900, null, null),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 2, 'Sauce', 'Stir the gochujang, sesame oil, sugar, vinegar and water into a smooth sauce.', null, null, null),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 3, 'Vegetables', 'Blanch the spinach in boiling salted water for 30 seconds, then the sprouts for 2 minutes. Rinse both under cold water, squeeze dry and season each with a little sesame oil and salt.', 240, null, null),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 4, 'Vegetables', 'In a skillet with a little vegetable oil, stir-fry the carrots, zucchini and mushrooms one at a time until just tender, 2–3 minutes each, seasoning each with a pinch of salt. Set each aside separately.', 480, null, null),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 5, 'Beef', 'Turn the heat to high and stir-fry the beef until browned, no pink remains and it reaches 145°F, 2–3 minutes.', 180, null, 62.8),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 6, 'To serve', 'Fry the eggs in the remaining oil until the whites are set and the edges are lacy, about 3 minutes (cover the pan for firmer yolks).', 180, null, null),
  ('b3eba16a-1699-4ccc-8b86-204d2d6a85fb', 7, null, 'Fill bowls with rice, arrange the vegetables and beef in sections on top, add an egg and sprinkle with sesame seeds. Serve with the sauce to stir in.', null, null, null);

