values ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'japchae-beef', 'japchae-e1f19e', 'Japchae', 'Glossy, chewy sweet potato glass noodles tossed with beef, spinach and colorful vegetables in a sesame-soy dressing — festive, and just as good at room temperature.', 'korean', 2, 30, 25, 55, 4, 'main', null, 0, array['stove']::text[], array['entertaining', 'make-ahead']::text[], array['Dangmyeon are sold in Korean and larger Asian grocers; vermicelli rice noodles work in a pinch but are softer.']::text[], 'https://images.unsplash.com/photo-1564834724105-918b73d1b9e0', 'Bowl of stir-fried glass noodles with mushrooms, onion and carrot', 'Ryan Kwok', 'https://unsplash.com/@milkbox', 'https://unsplash.com/photos/bowl-of-cooked-food-H6iSwrAOMG0', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner', 'entertaining']::text[], array['stir_fry', 'boil']::text[], array['savory']::text[], '{}'::text[], null, 'traditional', 'japchae', 'classic', 'Refrigerate up to 3 days. The noodles firm up when cold — microwave briefly or toss in a hot pan to soften.', null, 'owned', array['gluten', 'sesame', 'soy', 'wheat']::text[], array['beef']::text[], array['dairy_free']::text[], array['beef sirloin', 'soy sauce', 'garlic', 'starch noodle', 'spinach', 'yellow onion', 'carrot', 'bell pepper', 'shiitake mushroom', 'scallion', 'sesame oil', 'sesame seed']::text[], 'beef sirloin|bell pepper|carrot|garlic|scallion|sesame oil|sesame seed|shiitake mushroom|soy sauce|spinach|starch noodle|yellow onion',
  null, null, null, null, null, null, null, null)
