insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 1, 'Beef', 'Toss the beef with the soy sauce, sugar and garlic and set aside.', 600, null, null),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 2, 'Dressing', 'Stir the soy sauce, sugar, sesame oil and garlic together until the sugar dissolves.', null, null, null),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 3, 'Noodles', 'Boil the noodles until soft and chewy, 6–7 minutes. Drain, rinse briefly, snip into shorter lengths with scissors and toss with 1 tablespoon of the dressing.', 420, null, null),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 4, 'Noodles', 'Blanch the spinach for 30 seconds, rinse under cold water, squeeze dry and toss with a little dressing.', 60, null, null),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 5, 'Noodles', 'Heat half the oil in a large skillet over medium-high. Stir-fry the onion, carrot, bell pepper and mushrooms until crisp-tender, 4–5 minutes, adding the scallions for the last minute. Move to a large bowl.', 300, null, null),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 6, 'Beef', 'Add the rest of the oil and stir-fry the beef until browned, no pink remains and it reaches 145°F, 2–3 minutes.', 180, null, 62.8),
  ('e1f19ec9-53c9-4b22-a1de-75ec08442aa7', 7, null, 'Add the noodles, beef, spinach and remaining dressing to the vegetables and toss well with your hands or tongs. Sprinkle with sesame seeds and serve warm or at room temperature.', 120, null, null);

