values ('1e374f9a-8b54-4442-85b0-f565e22260fb', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'sundubu-jjigae-seafood', 'sundubu-jjigae-1e374f', 'Sundubu Jjigae', 'A fiery, bubbling stew of custardy soft tofu, clams and shrimp in a gochugaru-chili broth, with an egg cracked in at the end.', 'korean', 2, 15, 20, 35, 4, 'main', null, 0, array['stove']::text[], array['comfort']::text[], array['Gochugaru is sold at Korean and larger supermarkets; mild Aleppo pepper plus a pinch of cayenne is a workable stand-in.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['spicy', 'savory']::text[], '{}'::text[], null, 'traditional', 'sundubu-jjigae', 'classic', 'Best freshly made. Without the eggs, it keeps 1 day refrigerated.', 'The eggs here aren''t cooked to 160°F. Use pasteurized eggs if you''re serving anyone pregnant, very young, older, or with a weakened immune system.', 'owned', array['egg', 'fish', 'gluten', 'sesame', 'shellfish', 'soy', 'wheat']::text[], array['fish', 'shellfish', 'tofu']::text[], array['dairy_free']::text[], array['sesame oil', 'yellow onion', 'garlic', 'gochugaru', 'soy sauce', 'fish sauce', 'anchovy stock', 'littleneck clam', 'shrimp', 'extra-soft tofu', 'egg', 'scallion']::text[], 'anchovy stock|egg|extra-soft tofu|fish sauce|garlic|gochugaru|littleneck clam|scallion|sesame oil|shrimp|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
