insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('1e374f9a-8b54-4442-85b0-f565e22260fb', 1, null, 'Heat both oils in a wide pot or Korean earthenware pot over medium heat. Cook the onion and garlic until soft, 3 minutes. Stir in the gochugaru and cook 30 seconds until the oil turns red — don''t let it scorch.', 240, null, null),
  ('1e374f9a-8b54-4442-85b0-f565e22260fb', 2, null, 'Add the soy sauce, fish sauce and stock and bring to a boil. Add the zucchini and simmer 3 minutes.', 180, null, null),
  ('1e374f9a-8b54-4442-85b0-f565e22260fb', 3, null, 'Add the clams, cover and simmer until they open, 4–5 minutes. Throw away any that stay shut.', 300, null, null),
  ('1e374f9a-8b54-4442-85b0-f565e22260fb', 4, null, 'Spoon in the tofu in large pieces and add the shrimp. Simmer gently until the shrimp are pink and opaque (145°F), 2–3 minutes.', 180, null, 62.8),
  ('1e374f9a-8b54-4442-85b0-f565e22260fb', 5, null, 'Crack the eggs into the stew, cover and simmer until the whites set, 2–3 minutes. Scatter with scallions and serve bubbling, with rice.', 180, null, null);

