  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 6, 'Noodles', '1½ lb fresh wide rice noodles, or 12 oz dried wide rice noodles, soaked', 'fresh wide rice noodles', 1.5, 'lb', 'or 12 oz dried wide rice noodles, soaked', false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 7, 'Noodles', '1 lb boneless, skinless chicken thighs, thinly sliced', 'boneless, skinless chicken thighs', 1, 'lb', 'thinly sliced', false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 8, 'Noodles', '1 tsp soy sauce', 'soy sauce', 1, 'tsp', null, false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 9, 'Noodles', '1 tsp cornstarch', 'cornstarch', 1, 'tsp', null, false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 10, 'Noodles', '4 tbsp vegetable oil, divided', 'vegetable oil', 4, 'tbsp', 'divided', false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 11, 'Noodles', '4 cloves garlic, minced', 'garlic', 4, 'clove', 'minced', false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 12, 'Noodles', '1 bunch Chinese broccoli (gai lan), stems sliced, leaves cut into 2-inch pieces; or broccolini', 'Chinese broccoli (gai lan)', 1, 'bunch', 'stems sliced, leaves cut into 2-inch pieces; or broccolini', false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 13, 'Noodles', '3 large eggs', 'large eggs', 3, null, null, false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 14, 'To serve', '½ tsp white pepper', 'white pepper', 0.5, 'tsp', null, false),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 15, 'To serve', '1 tsp dried chili flakes', 'dried chili flakes', 1, 'tsp', null, true);
delete from public.recipe_instructions where recipe_id = 'a38575d4-ac27-4979-a3de-f37ab248ec48';
insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 1, 'Sauce', 'Stir the sauce ingredients together until the sugar dissolves.', null, null, null),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 2, 'Noodles', 'Separate the fresh noodles into single strands (microwave 30 seconds if they''re stiff). Toss the chicken with the soy sauce and cornstarch.', 300, null, null),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 3, 'Noodles', 'Heat 1 tablespoon oil in a wok or large skillet over high heat until smoking. Stir-fry the chicken until browned and 165°F, 3–4 minutes. Add the garlic and broccoli stems for 1 minute, then the leaves until just wilted. Move everything to a plate.', 300, null, 73.9),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 4, 'Noodles', 'Add 1 tablespoon oil, crack in the eggs and scramble until set, about 1 minute. Add to the plate.', 60, null, null),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 5, 'Noodles', 'Heat the remaining oil until smoking. Add half the noodles and half the sauce and spread them out. Let them sit 30–45 seconds to char, then toss and repeat for 2–3 minutes. Repeat with the rest.', 300, null, null),
  ('a38575d4-ac27-4979-a3de-f37ab248ec48', 6, null, 'Return the chicken, vegetables and egg to the wok and toss together. Season with white pepper and serve with chili flakes and a splash of vinegar at the table.', 60, null, null);

-- Green Curry with Chicken
