values ('a9c12c2b-b446-4971-afb4-a32b1f033cec', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'thai-green-curry-chicken', 'green-curry-with-chicken-a9c12c', 'Green Curry with Chicken', 'Chicken and eggplant simmered in coconut milk with green curry paste, lime leaves and Thai basil — rich, fragrant and as hot as you like.', 'thai', 2, 15, 25, 40, 4, 'main', null, 0, array['stove']::text[], array['weeknight']::text[], array['Curry pastes vary a lot in heat; start with 2 tablespoons and add more once it''s simmering.', 'Makrut lime leaves freeze beautifully; a strip of lime zest is a distant substitute.', 'Most Thai curry pastes contain shrimp paste — check the label if you''re cooking for someone with a shellfish allergy.']::text[], 'https://images.unsplash.com/photo-1668665772043-bdd32e348998', 'Bowl of Thai green curry with chicken', 'Andrew Relf', 'https://unsplash.com/@andrew_relf', 'https://unsplash.com/photos/a-bowl-of-food-qEzLiabQe8M', 'unsplash', true, 'public', false,
  'pending_review', array['main', 'dinner']::text[], array['stew', 'stir_fry']::text[], array['tangy', 'rich', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'green-curry-chicken', 'classic', 'Refrigerate up to 3 days or freeze up to 2 months (without the basil).', null, 'owned', array['fish']::text[], array['chicken', 'fish']::text[], array['dairy_free']::text[], array['coconut milk', 'curry paste', 'chicken stock', 'fish sauce', 'palm sugar', 'lime leave', 'japanese eggplant', 'bell pepper', 'basil leave', 'jasmine rice']::text[], 'basil leave|bell pepper|chicken stock|coconut milk|curry paste|fish sauce|japanese eggplant|jasmine rice|lime leave|palm sugar',
  null, null, null, null, null, null, null, null)
