  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 1, null, '27 oz canned coconut milk, two 13.5-oz cans, unshaken', 'canned coconut milk', 27, 'oz', 'two 13.5-oz cans, unshaken', false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 2, null, '3 tbsp Thai green curry paste, or to taste', 'Thai green curry paste', 3, 'tbsp', 'or to taste', false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 3, null, '1½ lb boneless, skinless chicken thighs, sliced bite-size', 'boneless, skinless chicken thighs', 1.5, 'lb', 'sliced bite-size', false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 4, null, '½ cup low-sodium chicken stock', 'low-sodium chicken stock', 0.5, 'cup', null, false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 5, null, '2 tbsp fish sauce', 'fish sauce', 2, 'tbsp', null, false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 6, null, '1 tbsp palm sugar, or light brown sugar', 'palm sugar', 1, 'tbsp', 'or light brown sugar', false),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 7, null, '6 makrut lime leaves, torn, center rib removed', 'makrut lime leaves', 6, null, 'torn, center rib removed', false),
