insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 1, null, 'Spoon the thick cream off the top of one can of coconut milk into a wok or pot. Simmer over medium heat, stirring, until it thickens and the oil starts to separate, 3–5 minutes.', 240, null, null),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 2, null, 'Add the curry paste and fry, stirring constantly, until very fragrant, 2 minutes.', 120, null, null),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 3, null, 'Add the chicken and stir to coat, then add the remaining coconut milk, stock, fish sauce, sugar and lime leaves. Bring to a gentle simmer.', 180, null, null),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 4, null, 'Add the eggplant and simmer until it is tender and the chicken reaches 165°F, 10–12 minutes.', 660, null, 73.9),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 5, null, 'Stir in the bell pepper and chiles for 2 minutes. Taste and balance with more fish sauce or sugar.', 120, null, null),
  ('a9c12c2b-b446-4971-afb4-a32b1f033cec', 6, null, 'Turn off the heat, stir in the basil and serve with jasmine rice.', null, null, null);

