values ('db084f2b-d7d1-4912-a122-116a7db90c19', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'tom-kha-gai', 'tom-kha-gai-db084f', 'Tom Kha Gai', 'A silky coconut soup with chicken and mushrooms, perfumed with galangal, lemongrass and lime leaves and finished sour with fresh lime.', 'thai', 2, 15, 25, 40, 4, 'main', null, 0, array['stove']::text[], array['comfort']::text[], array['Galangal is sold fresh or frozen at Asian grocers. Ginger gives a warmer, sharper flavor but still makes a good soup.', 'Torn oyster mushrooms are also traditional and give a silkier texture.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['soup', 'main', 'dinner', 'comfort']::text[], array['stew', 'boil']::text[], array['tangy', 'rich', 'fresh', 'savory']::text[], '{}'::text[], null, 'traditional', 'tom-kha-gai', 'classic', 'Refrigerate up to 3 days; reheat gently without boiling.', null, 'owned', array['fish']::text[], array['chicken', 'fish']::text[], array['dairy_free']::text[], array['chicken stock', 'coconut milk', 'galangal', 'lemongrass', 'lime leave', 'button mushroom', 'fish sauce', 'palm sugar', 'lime juice', 'cilantro']::text[], 'button mushroom|chicken stock|cilantro|coconut milk|fish sauce|galangal|lemongrass|lime juice|lime leave|palm sugar',
  null, null, null, null, null, null, null, null)
