  ('db084f2b-d7d1-4912-a122-116a7db90c19', 3, null, '1 piece fresh galangal, 2-inch piece, thinly sliced; or fresh ginger', 'fresh galangal', 1, 'piece', '2-inch piece, thinly sliced; or fresh ginger', false),
  ('db084f2b-d7d1-4912-a122-116a7db90c19', 4, null, '3 stalk lemongrass, bottom 4 inches, bruised and cut into 2-inch lengths', 'lemongrass', 3, 'stalk', 'bottom 4 inches, bruised and cut into 2-inch lengths', false),
