values ('7e35935c-d92b-45d3-b537-fc52d46b8f70', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'goi-cuon-summer-rolls', 'fresh-summer-rolls-goi-cuon-7e3593', 'Fresh Summer Rolls (Gỏi Cuốn)', 'Soft rice paper rolled around poached shrimp and pork, rice noodles and a garden of herbs, served with a creamy hoisin-peanut dip.', 'vietnamese', 2, 40, 25, 65, 6, 'starter', null, 0, array['stove']::text[], array['entertaining', 'make-ahead']::text[], array['Rice paper keeps softening after you dip it, so a quick dip is enough — it should still feel a little stiff when you lay it down.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['appetizer', 'entertaining']::text[], array['stew', 'boil']::text[], array['spicy', 'fresh']::text[], '{}'::text[], null, 'traditional', 'goi-cuon', 'classic', 'Best within 4 hours; keep covered with a damp towel. Refrigerated, they toughen by the next day.', null, 'owned', array['gluten', 'peanut', 'shellfish', 'soy', 'wheat']::text[], array['pork', 'shellfish']::text[], array['dairy_free']::text[], array['pork belly', 'shrimp', 'rice vermicelli', 'paper wrapper', 'leaf lettuce', 'mint leave', 'cilantro leave', 'hoisin sauce', 'peanut butter', 'garlic', 'roasted peanut']::text[], 'cilantro leave|garlic|hoisin sauce|leaf lettuce|mint leave|paper wrapper|peanut butter|pork belly|rice vermicelli|roasted peanut|shrimp',
  null, null, null, null, null, null, null, null)
