insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 1, 'Rolls', 'Put the pork in a small pot, cover with salted water and simmer until tender and 145°F in the center, 20–25 minutes. Cool, then slice very thin.', 1320, null, 62.8),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 2, 'Rolls', 'Bring the water back to a boil, add the shrimp and cook until pink and opaque, 2 minutes. Drain, cool, peel, devein and halve lengthwise.', 120, null, null),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 3, 'Rolls', 'Cook the vermicelli according to the package, rinse under cold water and drain well.', 240, null, null),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 4, 'Dip', 'Warm the hoisin, peanut butter, water and garlic in a small pan, whisking, until smooth, 2 minutes. Stir in the sriracha and cool; top with crushed peanuts to serve.', 120, null, null),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 5, 'Rolls', 'Dip a rice paper in warm water for 2–3 seconds and lay it on a damp board. On the lower third, layer lettuce, a little noodle, herbs and pork.', 60, null, null),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 6, 'Rolls', 'Fold the bottom over the filling and roll once, then fold in the sides. Lay 2 shrimp halves cut-side up on the paper, add a chive so it pokes out, and roll up snugly. Repeat with the rest.', 900, null, null),
  ('7e35935c-d92b-45d3-b537-fc52d46b8f70', 7, null, 'Serve the rolls with the dip, covered with a damp towel until you''re ready.', null, null, null);

