values ('9406f8c4-c75d-4034-9fad-780a4667a177', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'pancit-canton', 'pancit-canton-9406f8', 'Pancit Canton', 'Filipino party noodles — wheat flour sticks tossed with chicken, shrimp and crisp vegetables in a savory soy-oyster sauce, finished with calamansi.', 'filipino', 2, 25, 20, 45, 6, 'main', null, 0, array['stove']::text[], array['entertaining']::text[], array['Pancit canton noodles are sold in Filipino and many Asian grocers; they''re precooked and dried, so they soften fast — don''t boil them separately.']::text[], null, null, null, null, null, null, null, 'public', false,
  'pending_review', array['main', 'dinner', 'holiday', 'entertaining']::text[], array['stir_fry', 'boil']::text[], array['tangy', 'savory']::text[], array['birthday', 'potluck']::text[], null, 'traditional', 'pancit-canton', 'classic', 'Refrigerate up to 3 days; reheat in a skillet with a splash of stock.', null, 'owned', array['gluten', 'shellfish', 'soy', 'wheat']::text[], array['chicken', 'shellfish']::text[], array['dairy_free']::text[], array['yellow onion', 'garlic', 'shrimp', 'carrot', 'celery', 'green cabbage', 'snow pea', 'chicken stock', 'soy sauce', 'oyster sauce', 'pancit canton', 'scallion', 'calamansi']::text[], 'calamansi|carrot|celery|chicken stock|garlic|green cabbage|oyster sauce|pancit canton|scallion|shrimp|snow pea|soy sauce|yellow onion',
  null, null, null, null, null, null, null, null)
