insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 1, null, 'Blanch the spinach and green chile in boiling water for 1 minute, then plunge into ice water to keep the color. Drain, squeeze lightly and blend with ¼ cup water to a smooth purée.', 180, null, null),
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 2, null, 'Heat 1 tablespoon ghee in a nonstick skillet over medium-high heat and fry the paneer until golden on a few sides, 4–5 minutes. Drop into a bowl of warm water to keep it soft.', 300, null, null),
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 3, null, 'Heat the remaining ghee in a pot over medium heat. Add the cumin seeds and sizzle 30 seconds, then add the onion and cook until golden, 8–10 minutes.', 600, null, null),
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 4, null, 'Add the garlic and ginger for 1 minute, then the tomato, turmeric, coriander and half the garam masala. Cook until the tomato is soft and jammy, 4–5 minutes.', 300, null, null),
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 5, null, 'Stir in the spinach purée, salt and remaining water and simmer gently 5 minutes — longer dulls the green.', 300, null, null),
  ('e8305071-d1fb-41f8-a96e-1ca1cde33519', 6, null, 'Drain the paneer and add it with the cream, kasuri methi and remaining garam masala. Simmer 2 minutes and serve with rice or naan.', 120, null, null);

