values ('03715f5d-8af2-4035-bae7-36245e4d16f0', (select id from public.recipe_sources where name = 'Kitchen Pantry Test Kitchen'), 'lu-rou-fan', 'lu-rou-fan-03715f', 'Lu Rou Fan', 'Taiwan''s braised pork rice: finely diced pork belly simmered with fried shallots, soy, rock sugar and five-spice until glossy and spoonable.', 'taiwanese', 2, 20, 90, 110, 6, 'main', null, 0, array['stove', 'dutch_oven']::text[], array['comfort', 'make-ahead', 'freezer-friendly']::text[], array['Partly freezing the pork belly for 30 minutes makes the fine dice much easier.']::text[], 'https://images.unsplash.com/photo-1789296719187-829d74cc7711', 'Bowl of braised pork over rice with cucumber and yellow pickled radish', 'tommao wang', 'https://unsplash.com/@tommaomaoer', 'https://unsplash.com/photos/braised-pork-over-rice-bowl-K0VJlAT3FCs', 'unsplash', true, 'public', false,
  'pending_review', array['comfort', 'main', 'dinner']::text[], array['stew', 'boil']::text[], array['tangy', 'savory', 'aromatic']::text[], '{}'::text[], null, 'traditional', 'lu-rou-fan', 'classic', 'Refrigerate up to 5 days or freeze up to 3 months. The fat sets on top when cold; it melts back in as it reheats.', null, 'owned', array['egg', 'gluten', 'soy', 'wheat']::text[], array['pork']::text[], array['dairy_free']::text[], array['pork belly', 'shallot', 'garlic', 'shaoxing wine', 'soy sauce', 'rock sugar', 'five-spice powder', 'white pepper', 'jasmine rice']::text[], 'five-spice powder|garlic|jasmine rice|pork belly|rock sugar|shallot|shaoxing wine|soy sauce|white pepper',
