insert into public.recipe_instructions (recipe_id, position, component, body, timer_seconds, temperature_c, safe_internal_temp_c) values
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 1, null, 'Heat the oil in a Dutch oven over medium heat. Fry the shallots, stirring often, until evenly golden, 8–10 minutes. Lift out half for garnish.', 540, null, null),
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 2, null, 'Turn the heat to medium-high, add the pork belly and cook, stirring, until the fat renders and the pieces turn golden, 10 minutes. Spoon off excess fat, leaving about 2 tablespoons.', 600, null, null),
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 3, null, 'Add the garlic for 1 minute, then the Shaoxing wine to deglaze, scraping up the browned bits.', 60, null, null),
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 4, null, 'Stir in both soy sauces, the sugar, five-spice, white pepper, water and the reserved shallots. Bring to a boil.', 180, null, null),
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 5, null, 'Cover, lower the heat and simmer gently, stirring now and then, for 1 hour, adding the eggs after 30 minutes. The pork will be very tender and well past 145°F.', 3600, null, 62.8),
  ('03715f5d-8af2-4035-bae7-36245e4d16f0', 6, null, 'Uncover and simmer until the sauce is glossy and thick enough to coat a spoon, 10–15 minutes. Spoon the pork and sauce over rice with a halved egg and pickles.', 720, null, null);

